
.part-detail {
  border: 1px solid var(--c-border);
  border-radius: var(--r-radius);
  background: var(--c-panel);
  padding: 10px;
  box-shadow: var(--shadow-panel);
}

.d-head {
  display: flex;
  align-items: center;
  gap: 8px;
  border-bottom: 1px solid var(--c-border);
  padding-bottom: 6px;
  margin-bottom: 6px;
}

.d-name {
  font-size: 0.92rem;
  font-weight: bold;
  color: var(--c-text);
}

.d-state {
  font-size: 0.72rem;
  padding: 1px 8px;
  border-radius: var(--r-radius);
  border: 1px solid transparent;
}

.st-完好 { color: #41d8a3; border-color: #41d8a3; }
.st-受损 { color: #e8b64c; border-color: #e8b64c; }
.st-损毁 { color: #e56060; border-color: #e56060; }
.st-拆除 { color: #5c6675; border-color: #5c6675; }

.d-du {
  font-size: 0.82rem;
  font-weight: bold;
  color: var(--c-accent);
}

.d-desc {
  margin: 6px 0 8px;
  font-size: 0.76rem;
  line-height: 1.6;
  color: var(--c-text);
}

.d-dmg {
  margin: 4px 0 8px;
  font-size: 0.72rem;
  line-height: 1.6;
  color: var(--c-warn);
  border-left: 3px solid var(--c-border-light);
  padding-left: 6px;
}

.d-mods-title {
  font-size: 0.72rem;
  color: var(--c-accent);
  margin-bottom: 4px;
}

.d-mod-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 3px 4px;
  border-radius: var(--r-radius);
  cursor: pointer;
}

.d-mod-row:hover {
  background: var(--c-panel-2);
}

.dm-name {
  width: 64px;
  flex-shrink: 0;
  font-size: 0.72rem;
  color: var(--c-text-dim);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.track {
  flex: 1;
  height: 6px;
  border: 1px solid var(--c-border);
  background: var(--c-bg);
  overflow: hidden;
  border-radius: calc(var(--r-radius) / 2);
}

.track.big {
  height: 10px;
  margin-bottom: 6px;
}

.fill {
  height: 100%;
  transition: width 0.25s ease;
}

.dm-val {
  width: 30px;
  text-align: right;
  font-size: 0.72rem;
  color: var(--c-text-dim);
  flex-shrink: 0;
}

.d-back {
  margin-top: 8px;
  display: flex;
  gap: 8px;
}

.d-sub-tag {
  font-size: 0.66rem;
  color: var(--c-text-dim);
  border: 1px solid var(--c-border);
  border-radius: 999px;
  padding: 1px 8px;
}

/* 子部件列表 */
.d-subs {
  margin-top: 8px;
  border-top: 1px dashed var(--c-border);
  padding-top: 6px;
}

.d-subs-title {
  font-size: 0.72rem;
  color: var(--c-accent);
  margin-bottom: 4px;
  letter-spacing: 0.05em;
}

.d-sub-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 3px 6px;
  border-radius: var(--r-radius);
  cursor: pointer;
}

.d-sub-row:hover {
  background: var(--c-panel-2);
}

.d-sub-row.active {
  background: var(--c-accent-deep);
  outline: 1px solid color-mix(in srgb, var(--c-accent) 45%, transparent);
}

.ds-name {
  width: 92px;
  flex-shrink: 0;
  font-size: 0.72rem;
  color: var(--c-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ds-val {
  width: 42px;
  text-align: right;
  font-size: 0.7rem;
  color: var(--c-text-dim);
  flex-shrink: 0;
  font-variant-numeric: tabular-nums;
}

.d-back button {
  min-height: 36px;
  padding: 0 12px;
  border: 1px solid var(--c-border);
  background: var(--c-panel-2);
  color: var(--c-text);
  font-size: 0.76rem;
  cursor: pointer;
  border-radius: var(--r-radius);
}

.d-back .d-close {
  margin-left: auto;
  color: var(--c-text-dim);
}

/* 手机端：详情面板变为底部抽屉覆盖层（遮挡其他元素，节省空间） */
@media (max-width: 480px) {
  .part-detail {
    position: fixed;
    left: 8px;
    right: 8px;
    bottom: 8px;
    z-index: 100;
    max-height: 58vh;
    overflow-y: auto;
    background: var(--c-panel-2);
    border: 2px solid var(--c-accent);
    box-shadow: 0 -6px 24px rgba(0, 0, 0, 0.45);
  }

  .part-detail.empty {
    display: none;
  }
}

.d-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 18px 8px;
  color: var(--c-text-dim);
  font-size: 0.76rem;
  text-align: center;
}

.d-empty-icon {
  font-size: 1.4rem;
  color: var(--c-accent);
  opacity: 0.7;
}
