
.status-bar {
  padding: 8px 10px;
  display: flex;
  flex-direction: column;
  gap: 5px;
  border-bottom: 2px solid var(--c-border);
  background: var(--c-panel-2);
}

.top-line {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.console-title {
  font-weight: bold;
  letter-spacing: 0.04em;
  color: var(--c-text);
  font-size: 0.86rem;
  font-family: var(--font-title);
}

.btn-next {
  min-height: 44px;
  padding: 0 14px;
  border: 1px solid var(--c-accent);
  background: var(--c-accent);
  color: #06201c;
  font-weight: bold;
  font-size: 0.85rem;
  cursor: pointer;
  border-radius: var(--r-radius);
  box-shadow: 0 2px 0 rgba(0, 0, 0, 0.25);
}

.btn-next:active {
  transform: translateY(2px) scale(0.98);
  box-shadow: none;
}

.row {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.label {
  color: var(--c-text-dim);
  font-size: 0.75rem;
}

.value {
  font-weight: bold;
  font-size: 0.82rem;
}

.value.accent {
  color: var(--c-accent);
}

.value.warn {
  color: var(--c-danger);
}

.hint {
  color: var(--c-text-dim);
  font-size: 0.7rem;
  margin-left: 2px;
}

.power-row {
  padding: 2px 0;
}

.track {
  flex: 1;
  min-width: 70px;
  height: 8px;
  border: 1px solid var(--c-border);
  background: var(--c-bg);
  overflow: hidden;
  border-radius: calc(var(--r-radius) / 2);
}

.fill {
  height: 100%;
  background: linear-gradient(90deg, color-mix(in srgb, var(--c-accent) 65%, #000), var(--c-accent));
  transition: width 0.25s ease;
}

.fill.low {
  animation: bd-breathe 1.1s ease-in-out infinite;
}

.value.val-low {
  color: var(--c-danger);
  animation: bd-breathe 1.1s ease-in-out infinite;
}

.tip {
  background: var(--c-panel);
  border: 1px solid var(--c-border-light);
  border-left: 3px solid var(--c-accent);
  padding: 6px 8px;
  font-size: 0.75rem;
  color: var(--c-text);
  line-height: 1.5;
}
