
/* 独立拟真「临街门面」：暖橙铁灰，不随四主题 */
.repair-shop {
  display: flex;
  flex-direction: column;
  gap: 12px;
  border: 1px solid #4a3826;
  border-radius: 12px;
  background: linear-gradient(170deg, #1c1813 0%, #12100d 100%);
  padding: 14px;
  box-shadow: 0 4px 18px rgba(180, 110, 40, 0.18);
}

/* ---- 店招 ---- */
.rs-sign {
  display: flex;
  align-items: center;
  gap: 12px;
  border-bottom: 2px solid #e8a34c;
  padding-bottom: 10px;
  flex-wrap: wrap;
}

.rs-back {
  min-height: 40px;
  padding: 0 14px;
  border: 1px solid #5a4630;
  border-radius: 8px;
  background: #241d15;
  color: #e8c9a3;
  font-size: 0.78rem;
  cursor: pointer;
}

.rs-brand {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 160px;
}

.rs-hammer {
  font-size: 1.5rem;
  line-height: 1;
  filter: drop-shadow(0 0 8px rgba(232, 163, 76, 0.6));
}

.rs-title-wrap {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.rs-title {
  font-size: 1.12rem;
  font-weight: bold;
  color: #ffcf8a;
  letter-spacing: 0.08em;
  text-shadow: 0 0 12px rgba(232, 163, 76, 0.45);
}

.rs-sub {
  font-size: 0.66rem;
  color: #a08a68;
}

.rs-open {
  font-size: 0.64rem;
  color: #7fd48f;
  border: 1px solid #3c5a41;
  border-radius: 6px;
  padding: 2px 8px;
  background: rgba(80, 180, 110, 0.1);
  letter-spacing: 0.1em;
}

/* ---- 送修横幅 ---- */
.rs-delivery {
  border: 1px solid #8a4a3a;
  border-left: 4px solid #ff7a6b;
  border-radius: 10px;
  background: rgba(180, 60, 40, 0.12);
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.dl-title {
  font-size: 0.88rem;
  font-weight: bold;
  color: #ff9a8a;
}

.dl-desc {
  font-size: 0.72rem;
  color: #c9a08a;
  line-height: 1.5;
}

/* ---- 卡片 ---- */
.rs-card {
  border: 1px solid #3a2f22;
  border-radius: 10px;
  background: #181410;
  padding: 12px;
}

.rs-card-head {
  font-size: 0.86rem;
  font-weight: bold;
  color: #ffcf8a;
  border-bottom: 1px solid #3a2f22;
  padding-bottom: 6px;
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.rs-card-head em {
  font-style: normal;
  font-size: 0.68rem;
  color: #8a7a60;
  font-weight: normal;
}

.repair-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  max-height: 240px;
  overflow-y: auto;
}

.repair-bands {
  margin-top: 6px;
  font-size: 0.7rem;
  color: #8a7a60;
}

.repair-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 6px;
  border: 1px solid #2e2618;
  background: #201a14;
  border-radius: 8px;
}

.r-name {
  flex: 1;
  font-size: 0.76rem;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #e8c9a3;
}

.r-du {
  width: 52px;
  text-align: right;
  font-size: 0.72rem;
  color: #a08a68;
  flex-shrink: 0;
}

.r-level {
  font-size: 0.7rem;
  color: #ffb36b;
  border: 1px solid #5a4630;
  padding: 0 5px;
  border-radius: 6px;
  flex-shrink: 0;
}

.r-fee {
  width: 66px;
  text-align: right;
  font-size: 0.72rem;
  color: #ffb36b;
  flex-shrink: 0;
}

.r-fee.ok {
  color: #7fd48f;
}

.r-time {
  font-size: 0.66rem;
  color: #8a7a60;
  border: 1px solid #3a2f22;
  padding: 0 5px;
  border-radius: 6px;
  flex-shrink: 0;
}

.r-queued {
  font-size: 0.7rem;
  color: #5aa7f0;
  border: 1px solid #3a5a70;
  padding: 0 5px;
  border-radius: 6px;
  flex-shrink: 0;
}

.st-完好 { color: #7fd48f; }
.st-受损 { color: #ffb36b; }
.st-损毁 { color: #ff7a6b; }
.st-拆除 { color: #6a7580; }

.r-btn {
  min-height: 44px;
  padding: 0 12px;
  border: 1px solid #e8a34c;
  background: rgba(232, 163, 76, 0.12);
  color: #ffcf8a;
  font-size: 0.76rem;
  cursor: pointer;
  border-radius: 8px;
  flex-shrink: 0;
}

.r-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.r-btn.wide {
  width: 100%;
  border-color: #e8a34c;
  color: #ffcf8a;
  font-weight: bold;
  background: rgba(232, 163, 76, 0.18);
}

.body-replace {
  margin-top: 8px;
}

/* ---- 更换部件 ---- */
.slot-block {
  border: 1px solid #2e2618;
  background: #201a14;
  border-radius: 8px;
  padding: 6px;
  margin-bottom: 4px;
}

.slot-head {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  padding-bottom: 4px;
  border-bottom: 1px dashed #2e2618;
  margin-bottom: 4px;
}

.slot-cur {
  font-size: 0.68rem;
  color: #a08a68;
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.slot-tag {
  font-size: 0.64rem;
  color: #7fd48f;
  border: 1px solid #3c5a41;
  border-radius: 6px;
  padding: 0 6px;
  flex-shrink: 0;
}

.slot-tag.need {
  color: #ffb36b;
  border-color: #5a4630;
  background: rgba(232, 163, 76, 0.08);
}

.slot-cands {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.cand {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 2px 4px;
  border-radius: 6px;
}

.cand:hover {
  background: rgba(232, 163, 76, 0.06);
}

.c-name {
  font-size: 0.74rem;
  color: #e8c9a3;
  flex-shrink: 0;
}

.c-eff {
  flex: 1;
  font-size: 0.66rem;
  color: #8a7a60;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.c-out {
  font-size: 0.64rem;
  color: #6a7580;
  flex-shrink: 0;
}

.cand-empty {
  font-size: 0.68rem;
  color: #6a7580;
  padding: 2px 4px;
}

/* ---- 商店：购买 ---- */
.shop-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(170px, 1fr));
  gap: 6px;
  max-height: 240px;
  overflow-y: auto;
}

.shop-item {
  border: 1px solid #2e2618;
  background: #201a14;
  border-radius: 8px;
  padding: 6px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.si-main {
  display: flex;
  align-items: center;
  gap: 6px;
}

.si-name {
  font-size: 0.76rem;
  font-weight: bold;
  color: #e8c9a3;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.si-tag {
  font-size: 0.6rem;
  color: #8a7a60;
  border: 1px solid #3a2f22;
  border-radius: 5px;
  padding: 0 5px;
  flex-shrink: 0;
}

.si-eff {
  font-size: 0.66rem;
  color: #a08a68;
  line-height: 1.4;
}

.si-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  margin-top: 2px;
}

.si-price {
  font-size: 0.72rem;
  color: #ffb36b;
}

.si-foot .r-btn {
  min-height: 32px;
  padding: 0 10px;
  font-size: 0.7rem;
}

.tip {
  background: #201a14;
  border: 1px solid #3a2f22;
  border-left: 3px solid #e8a34c;
  padding: 8px 10px;
  font-size: 0.76rem;
  line-height: 1.6;
  color: #e8c9a3;
}
