
.settings-panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.card {
  border: 1px solid var(--c-border);
  border-radius: var(--r-radius);
  background: var(--c-panel);
  padding: 10px;
}

.head {
  font-size: 0.86rem;
  font-weight: bold;
  color: var(--c-accent);
  border-bottom: 1px solid var(--c-border);
  padding-bottom: 5px;
  margin-bottom: 8px;
}

.opt-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.opt {
  min-height: 44px;
  min-width: 64px;
  padding: 0 16px;
  border: 1px solid var(--c-border);
  background: var(--c-panel-2);
  color: var(--c-text);
  font-size: 0.82rem;
  cursor: pointer;
  border-radius: var(--r-radius);
}

.opt.active {
  border-color: var(--c-accent);
  color: var(--c-accent);
  background: var(--c-accent-deep);
  font-weight: bold;
}

.opt-sm {
  min-width: 48px;
  min-height: 36px;
  padding: 0 12px;
}

.opt-label {
  font-size: 0.76rem;
  color: var(--c-text);
  margin: 8px 0 4px;
}

.slider-row {
  display: flex;
  align-items: center;
  gap: 10px;
}

.slider-row input[type='range'] {
  flex: 1;
  accent-color: var(--c-accent);
  min-height: 28px;
}

.slider-val {
  min-width: 42px;
  text-align: right;
  font-size: 0.78rem;
  color: var(--c-accent);
  font-variant-numeric: tabular-nums;
}

/* 主题按钮：用各主题配色预览（浅色主题下可读性优先） */
.theme-row {
  gap: 6px;
}

.theme-opt {
  min-width: 86px;
  border-radius: var(--r-radius);
  box-shadow: var(--shadow-panel);
}

.th-深色控制台 {
  border-color: #2a3448;
  color: #dde4ee;
  background: #141a25;
}

.th-深色控制台.active {
  border-color: #3fd6c4;
  color: #3fd6c4;
  background: #103f3a;
}

.th-暖色日常 {
  border-color: #e0cfa9;
  color: #4a3a26;
  background: #fffaf1;
}

.th-暖色日常.active {
  border-color: #df7a35;
  color: #df7a35;
  background: #f8e2cd;
}

.th-复古终端 {
  border-color: #27411a;
  color: #b6f27e;
  background: #0f1b0a;
}

.th-复古终端.active {
  border-color: #7dff4f;
  color: #7dff4f;
  background: #18330d;
}

.th-机械工坊 {
  border-color: #4d3b26;
  color: #e6d6ba;
  background: #211a13;
}

.th-机械工坊.active {
  border-color: #e88a2a;
  color: #e88a2a;
  background: #3b2910;
}

.danger {
  min-height: 44px;
  padding: 0 16px;
  border: 1px solid var(--c-danger);
  background: transparent;
  color: var(--c-danger);
  font-size: 0.82rem;
  cursor: pointer;
  border-radius: var(--r-radius);
}

.wiz-btn {
  min-height: 44px;
  padding: 0 16px;
  border: 1px solid var(--c-accent);
  background: transparent;
  color: var(--c-accent);
  font-size: 0.82rem;
  cursor: pointer;
  border-radius: var(--r-radius);
}

.workshop ul {
  margin: 8px 0;
  padding-left: 18px;
  color: var(--c-text);
  font-size: 0.76rem;
  line-height: 1.7;
}

.workshop {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.note {
  margin-top: 10px;
  color: var(--c-text-dim);
  font-size: 0.72rem;
  line-height: 1.6;
}

/* ---------- 创意工坊 ---------- */
.ws-open {
  width: 100%;
  min-height: 44px;
  border: 1px solid var(--c-accent);
  background: var(--c-accent-deep);
  color: var(--c-accent);
  border-radius: var(--r-radius);
  font-size: 0.82rem;
  font-weight: bold;
  cursor: pointer;
}

/* 创意工坊编辑器（全屏 overlay） */
.ws-mask {
  position: fixed;
  inset: 0;
  z-index: 300;
  background: rgba(0, 0, 0, 0.55);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  box-sizing: border-box;
}

.ws-editor {
  width: min(720px, 100%);
  max-height: calc(100vh - 48px);
  display: flex;
  flex-direction: column;
  border: 1px solid var(--c-border);
  border-radius: 12px;
  background: var(--c-panel);
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.45);
  overflow: hidden;
}

.ws-ed-head {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  border-bottom: 1px solid var(--c-border);
  background: var(--c-panel-2);
}

.ws-ed-title {
  font-size: 0.86rem;
  font-weight: bold;
  color: var(--c-accent);
  flex: 1;
}

.ws-x {
  min-height: 36px;
  padding: 0 12px;
  border: 1px solid var(--c-border);
  background: var(--c-panel);
  color: var(--c-text-dim);
  border-radius: 8px;
  font-size: 0.74rem;
  cursor: pointer;
}

.ws-ed-body {
  flex: 1 1 auto;
  min-height: 0;
  padding: 12px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.ws-ed-body > * {
  flex-shrink: 0;
}

/* 创建 / 编辑物品定义（主操作区） */
.ws-create {
  border: 1px solid color-mix(in srgb, var(--c-accent) 55%, var(--c-border));
  border-radius: 12px;
  background: linear-gradient(160deg, color-mix(in srgb, var(--c-accent) 12%, var(--c-panel-2)), var(--c-panel-2));
  overflow: hidden;
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--c-accent) 18%, transparent);
}

.ws-create.on {
  border-color: var(--c-accent);
  box-shadow: 0 0 0 1px var(--c-accent), 0 4px 18px color-mix(in srgb, var(--c-accent) 22%, transparent);
}

.ws-create-head {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 10px;
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 12px 14px;
  text-align: left;
}

.ws-create-head:hover {
  background: color-mix(in srgb, var(--c-accent) 6%, transparent);
}

.wc-icon {
  width: 30px;
  height: 30px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: var(--c-accent-deep);
  color: var(--c-accent);
  font-size: 0.9rem;
  font-weight: bold;
}

.wc-main {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.wc-title {
  font-size: 0.84rem;
  font-weight: bold;
  color: var(--c-accent);
}

.wc-sub {
  font-size: 0.66rem;
  color: var(--c-text-dim);
}

.ws-create-body {
  padding: 12px 14px;
  border-top: 1px dashed color-mix(in srgb, var(--c-accent) 35%, var(--c-border));
  display: flex;
  flex-direction: column;
  gap: 8px;
}

/* AI 补全按钮 */
.wf-label-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.wf-ai {
  min-height: 24px;
  padding: 0 10px;
  margin-left: auto;
  border: 1px solid color-mix(in srgb, var(--c-accent) 50%, var(--c-border));
  background: color-mix(in srgb, var(--c-accent) 10%, var(--c-panel));
  color: var(--c-accent);
  border-radius: 999px;
  font-size: 0.66rem;
  cursor: pointer;
}

.wf-ai:hover {
  background: color-mix(in srgb, var(--c-accent) 18%, var(--c-panel));
}

/* 折叠区 */
.ws-fold {
  border: 1px solid var(--c-border);
  border-radius: var(--r-radius);
  background: var(--c-panel-2);
  overflow: hidden;
}

.ws-fold-head {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 8px;
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 10px 12px;
  font-size: 0.8rem;
  color: var(--c-text);
  font-weight: bold;
  text-align: left;
}

.ws-fold-head:hover {
  background: color-mix(in srgb, var(--c-accent) 6%, transparent);
  color: var(--c-accent);
}

.ws-fold-head::before {
  content: '';
  width: 3px;
  height: 14px;
  border-radius: 2px;
  background: color-mix(in srgb, var(--c-accent) 60%, transparent);
}

.ws-fold-body {
  padding: 10px 12px;
  border-top: 1px dashed var(--c-border);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.ws-item {
  transition: border-color 0.15s, box-shadow 0.15s;
}

.ws-item:hover {
  border-color: color-mix(in srgb, var(--c-accent) 45%, var(--c-border));
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--c-accent) 25%, transparent);
}

.ws-empty {
  font-size: 0.74rem;
  color: var(--c-text-dim);
  padding: 8px 0;
}

/* 目录搜索 / 筛选工具栏 */
.ws-toolbar {
  display: flex;
  gap: 8px;
  align-items: center;
}

.ws-toolbar input {
  flex: 1;
  min-width: 0;
  min-height: 36px;
  border: 1px solid var(--c-border);
  border-radius: 8px;
  background: var(--c-panel);
  color: var(--c-text);
  padding: 0 10px;
  font-size: 0.76rem;
}

.ws-toolbar select {
  min-height: 36px;
  border: 1px solid var(--c-border);
  border-radius: 8px;
  background: var(--c-panel);
  color: var(--c-text);
  padding: 0 6px;
  font-size: 0.76rem;
}

/* 折叠区固定高度 + 内部滚动（翻页式） */
.ws-fold-body {
  padding: 10px 12px;
  border-top: 1px dashed var(--c-border);
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 300px;
  overflow-y: auto;
}

.ws-fold-body > * {
  flex-shrink: 0;
}

/* 官方条目内的子目录（部件配置） */
.ws-fold.sub {
  border-color: color-mix(in srgb, var(--c-accent) 35%, var(--c-border));
}

/* 批量操作 */
.ws-batch {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

/* 实时预览卡 */
.ws-preview {
  border: 1px dashed color-mix(in srgb, var(--c-accent) 45%, var(--c-border));
  border-radius: 10px;
  padding: 10px 12px;
  background: color-mix(in srgb, var(--c-accent) 5%, var(--c-panel));
}

.wp-head {
  font-size: 0.7rem;
  font-weight: bold;
  color: var(--c-accent);
  margin-bottom: 8px;
}

.wp-card {
  border: 1px solid var(--c-border);
  border-radius: 8px;
  padding: 10px 12px;
  background: var(--c-panel);
}

.wp-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
}

.wp-name {
  font-size: 0.9rem;
  font-weight: bold;
  color: var(--c-text);
}

.wp-effect {
  font-size: 0.78rem;
  color: var(--c-accent);
  margin-bottom: 4px;
}

.wp-desc {
  font-size: 0.72rem;
  color: var(--c-text-dim);
  margin-bottom: 4px;
}

.wp-meta {
  font-size: 0.7rem;
  color: var(--c-text-dim);
}

/* 导入合并策略选择 */
.ws-mode {
  min-height: 32px;
  border: 1px solid var(--c-border);
  border-radius: 8px;
  background: var(--c-panel);
  color: var(--c-text);
  padding: 0 6px;
  font-size: 0.7rem;
}

/* 购买来源勾选 */
.wf-checks {
  display: flex;
  gap: 14px;
  align-items: center;
  flex-wrap: wrap;
}

.wf-check {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 0.74rem;
  color: var(--c-text);
  cursor: pointer;
}

.wf-check input {
  width: 15px;
  height: 15px;
  accent-color: var(--c-accent);
}

.ws-hint {
  font-size: 0.66rem;
  color: var(--c-text-dim);
}

.ws-head {
  width: 100%;
  text-align: left;
  display: flex;
  align-items: center;
  gap: 8px;
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 0;
  font-size: 0.82rem;
  color: var(--c-text);
  font-weight: bold;
}

.ws-sub {
  font-weight: normal;
  font-size: 0.68rem;
  color: var(--c-text-dim);
}

.ws-caret {
  margin-left: auto;
  font-size: 0.7rem;
  color: var(--c-text-dim);
}

.ws-note {
  font-size: 0.72rem;
  color: var(--c-text-dim);
  line-height: 1.6;
  margin: 0 0 8px;
}

.ws-add {
  width: 100%;
  min-height: 44px;
  border: 1px dashed var(--c-accent);
  background: color-mix(in srgb, var(--c-accent) 8%, var(--c-panel));
  color: var(--c-accent);
  border-radius: var(--r-radius);
  font-size: 0.8rem;
  cursor: pointer;
  margin-bottom: 8px;
}

.ws-form {
  display: flex;
  flex-direction: column;
  gap: 6px;
  border: 1px solid var(--c-border);
  background: var(--c-panel-2);
  border-radius: var(--r-radius);
  padding: 8px;
  margin-bottom: 8px;
}

.wf-row {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.wf-row label {
  font-size: 0.7rem;
  color: var(--c-text-dim);
}

.wf-row input,
.wf-row select,
.wf-row textarea {
  border: 1px solid var(--c-border);
  background: var(--c-panel);
  color: var(--c-text);
  border-radius: 6px;
  padding: 6px 8px;
  font-size: 0.78rem;
  min-height: 34px;
  font-family: inherit;
}

.wf-actions {
  display: flex;
  gap: 8px;
  margin-top: 2px;
}

.wf-save,
.wf-cancel {
  min-height: 40px;
  padding: 0 14px;
  border-radius: 8px;
  font-size: 0.78rem;
  cursor: pointer;
}

.wf-save {
  border: 1px solid var(--c-accent);
  background: var(--c-accent-deep);
  color: var(--c-accent);
  font-weight: bold;
}

.wf-save:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.wf-cancel {
  border: 1px solid var(--c-border);
  background: var(--c-panel);
  color: var(--c-text-dim);
}

.ws-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-bottom: 8px;
}

.ws-sec {
  font-size: 0.7rem;
  color: var(--c-accent);
  border-bottom: 1px dashed var(--c-border);
  padding-bottom: 3px;
  margin: 4px 0 2px;
}

.ws-item {
  display: flex;
  align-items: center;
  gap: 8px;
  border: 1px solid var(--c-border);
  background: var(--c-panel-2);
  border-radius: var(--r-radius);
  padding: 6px 8px;
  flex-wrap: wrap;
}

.ws-item.off {
  opacity: 0.55;
}

.wi-main {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 90px;
  flex-shrink: 0;
}

.wi-name {
  font-weight: bold;
  font-size: 0.8rem;
}

.wi-tag {
  font-size: 0.66rem;
  color: var(--c-text-dim);
}

.wi-tag.own {
  color: var(--c-accent);
}

.wi-effect {
  flex: 1;
  min-width: 80px;
  font-size: 0.72rem;
  color: var(--c-text-dim);
}

.wi-ops {
  display: flex;
  gap: 6px;
  flex-shrink: 0;
}

.wi-btn {
  min-height: 34px;
  padding: 0 10px;
  border: 1px solid var(--c-border);
  background: var(--c-panel);
  color: var(--c-text);
  border-radius: 8px;
  font-size: 0.7rem;
  cursor: pointer;
}

.wi-btn.danger {
  color: var(--c-danger);
  border-color: color-mix(in srgb, var(--c-danger) 45%, var(--c-border));
}

.ws-io {
  display: flex;
  gap: 8px;
}

/* ---------- 部件配置（创意工坊接口） ---------- */
.ws-parts {
  border-top: 1px dashed var(--c-border);
  margin-top: 10px;
  padding-top: 8px;
}

.pf-list {
  margin-top: 4px;
}

.pf-row {
  align-items: flex-start;
  flex-direction: column;
}

.pf-fields {
  display: flex;
  flex-direction: column;
  gap: 4px;
  width: 100%;
  min-width: 0;
}

.pf-fields input {
  width: 100%;
  min-height: 30px;
  border: 1px solid var(--c-border);
  background: var(--c-panel);
  color: var(--c-text);
  border-radius: 6px;
  padding: 4px 8px;
  font-size: 0.72rem;
  box-sizing: border-box;
}

.pf-row .wi-ops {
  align-self: flex-end;
}

.tip {
  background: var(--c-panel);
  border: 1px solid var(--c-border-light);
  border-left: 3px solid var(--c-accent);
  padding: 8px 10px;
  font-size: 0.76rem;
  line-height: 1.6;
  color: var(--c-text);
  border-radius: var(--r-radius);
}
