
.body-panel-v5 {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

/* ---- 菜单横条（全宽） ---- */
.menu-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 8px;
  border: 1px solid var(--c-border);
  border-radius: var(--r-radius);
  background: var(--c-panel);
  box-shadow: var(--shadow-panel);
  overflow-x: auto;
  scrollbar-width: none;
  flex-wrap: nowrap;
}

.menu-bar::-webkit-scrollbar {
  display: none;
}

.mb-item {
  min-height: 32px;
  padding: 0 12px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--c-text-dim);
  font-size: 0.76rem;
  cursor: pointer;
  border-radius: calc(var(--r-radius) / 1.4);
  white-space: nowrap;
  flex: none;
  transition: background 0.15s, color 0.15s;
}

.mb-item:hover {
  background: var(--c-panel-2);
  color: var(--c-text);
}

.mb-item.on {
  background: var(--c-accent-deep);
  color: var(--c-accent);
  border-color: color-mix(in srgb, var(--c-accent) 45%, transparent);
  font-weight: bold;
}

.mb-item.parent {
  font-weight: bold;
  color: var(--c-text);
}

.mb-item.parent.open {
  color: var(--c-accent);
}

.mb-sep {
  font-size: 0.64rem;
  color: var(--c-text-dim);
  letter-spacing: 0.1em;
  border-left: 1px solid var(--c-border);
  padding-left: 8px;
  margin-left: 2px;
  flex: none;
}

.caret {
  font-size: 0.6rem;
  margin-right: 3px;
}

/* ---- 四肢展开：悬浮浮层，不占布局空间 ---- */
.limb-bar {
  position: absolute;
  top: 54px;
  left: 0;
  right: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 7px 8px;
  border: 1px solid var(--c-border);
  border-radius: var(--r-radius);
  background: var(--c-panel);
  box-shadow: 0 10px 24px rgba(0, 0, 0, 0.4);
  overflow-x: auto;
  scrollbar-width: none;
  flex-wrap: nowrap;
}

.limb-bar::-webkit-scrollbar {
  display: none;
}

.limb-item {
  min-height: 30px;
  padding: 0 10px;
  border: 1px solid var(--c-border);
  background: var(--c-panel-2);
  color: var(--c-text-dim);
  font-size: 0.72rem;
  cursor: pointer;
  border-radius: calc(var(--r-radius) / 1.4);
  white-space: nowrap;
  flex: none;
}

.limb-item.on {
  border-color: var(--c-accent);
  color: var(--c-accent);
  background: var(--c-accent-deep);
  font-weight: bold;
}

/* ---- 主体 ---- */
.main-area {
  display: flex;
  gap: 12px;
  align-items: stretch;
}

/* 左：人体图（无底，裸放；列高与右栏面板严格一致 475px，内部 svg 弹性填满） */
.body-col {
  flex: none;
  width: 300px;
  height: 475px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.body-col :deep(.body-diagram) {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
}

.body-col :deep(.body-svg) {
  flex: 1;
  min-height: 0;
  width: 100%;
  max-width: 292px;
  max-height: 100%;
  margin: 0 auto;
}

.body-col :deep(.legend) {
  flex: none;
}

.body-col :deep(.hint-line) {
  flex: none;
}

/* 右：完整面板底 = 与功能模块同尺寸（15 条完整容纳） */
.view-area {
  flex: 1;
  min-width: 0;
  height: 475px;
  border: 1px solid var(--c-border);
  border-radius: var(--r-radius);
  background: var(--c-panel);
  box-shadow: var(--shadow-panel);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* 关闭按钮：仅手机端悬浮层使用，电脑端隐藏 */
.view-close {
  display: none;
}

/* ① 主显示区：区内滚动，切换内容不跳变 */
.view-main {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  scrollbar-width: none;
  display: flex;
  flex-direction: column;
}

.view-main::-webkit-scrollbar {
  display: none;
}

/* ---- 总览折叠卡（面板内部，无独立外框） ---- */
.ov-card {
  border: none;
  border-bottom: 1px solid var(--c-border);
  border-radius: 0;
}

.ov-head {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 38px;
  padding: 0 12px;
  background: var(--c-panel-2);
  border: none;
  color: var(--c-accent);
  font-size: 0.82rem;
  font-weight: bold;
  cursor: pointer;
  letter-spacing: 0.04em;
}

.ov-head .caret {
  font-size: 0.7rem;
  color: var(--c-text-dim);
  font-style: normal;
  margin: 0;
}

.ov-body {
  padding: 8px 12px;
}

.ov-stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(80px, 1fr));
  gap: 6px;
  margin-bottom: 8px;
}

.ov-stat {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 8px;
  border: 1px solid var(--c-border);
  border-radius: var(--r-radius);
  background: var(--c-panel-2);
}

.dot {
  width: 10px;
  height: 10px;
  border-radius: 2px;
  display: inline-block;
  flex-shrink: 0;
}

.dot-完好 { background: #41d8a3; }
.dot-受损 { background: #e8b64c; }
.dot-损毁 { background: #e56060; }
.dot-拆除 { background: #5c6675; }

.ov-name {
  font-size: 0.72rem;
  color: var(--c-text-dim);
}

.ov-num {
  margin-left: auto;
  font-size: 0.86rem;
}

.ov-完好 { color: var(--c-ok); }
.ov-受损 { color: var(--c-warn); }
.ov-损毁 { color: var(--c-danger); }
.ov-拆除 { color: var(--c-removed); }

.ov-sub {
  font-size: 0.72rem;
  color: var(--c-accent);
  margin-bottom: 4px;
}

.ov-modules {
  margin-bottom: 8px;
}

.ov-low {
  display: flex;
  justify-content: space-between;
  font-size: 0.74rem;
  color: var(--c-text);
  padding: 3px 6px;
  border-radius: var(--r-radius);
}

.ov-low:nth-child(odd) {
  background: var(--c-panel-2);
}

.ov-low-du {
  color: var(--c-danger);
  font-weight: bold;
}

.ov-none {
  font-size: 0.74rem;
  color: var(--c-ok);
  padding: 3px 6px;
}

/* ---- ② 部件卡（吸附区，v5：无总览块，只有子部件/模块卡，点击平滑展开） ---- */
.view-parts {
  flex: none;
  border-top: 1px solid color-mix(in srgb, var(--c-accent) 40%, var(--c-border));
  background: color-mix(in srgb, var(--c-accent-deep) 45%, var(--c-panel));
  padding: 8px 12px 10px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.vp-title {
  font-size: 0.62rem;
  letter-spacing: 0.16em;
  color: var(--c-text-dim);
}

.part-blocks {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.part-block {
  border: 1px solid var(--c-border);
  border-radius: 10px;
  background: color-mix(in srgb, var(--c-panel) 82%, #000);
  padding: 7px 10px;
  cursor: pointer;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.part-block:hover { border-color: color-mix(in srgb, var(--c-accent) 55%, var(--c-border)); }

.part-block.open {
  border-color: var(--c-accent);
  box-shadow: 0 5px 14px color-mix(in srgb, var(--c-accent) 14%, transparent);
}

.part-block.active {
  border-color: var(--c-accent);
  background: color-mix(in srgb, var(--c-accent) 10%, var(--c-panel));
}

.pb-status {
  display: flex;
  align-items: center;
  gap: 8px;
}

.pb-name {
  font-size: 0.76rem;
  font-weight: bold;
  color: var(--c-accent);
  flex-shrink: 0;
}

.pb-tag {
  font-size: 0.56rem;
  color: var(--c-text-dim);
  border: 1px solid var(--c-border);
  border-radius: 999px;
  padding: 0 6px;
  flex-shrink: 0;
}

.pb-bar {
  flex: 1;
  height: 7px;
  border-radius: 4px;
  background: var(--c-border);
  overflow: hidden;
  min-width: 40px;
}

.pb-bar i {
  display: block;
  height: 100%;
  border-radius: 4px;
}

.bar-hi { background: #41d8a3; }
.bar-mid { background: #e8b64c; }
.bar-lo { background: #e58f3c; }
.bar-crit { background: #e56060; }

.pb-du {
  font-size: 0.68rem;
  color: var(--c-text-dim);
  flex-shrink: 0;
  font-variant-numeric: tabular-nums;
}

.pb-arrow {
  font-size: 0.62rem;
  color: var(--c-text-dim);
  flex-shrink: 0;
  transition: transform 0.25s ease;
}

.part-block.open .pb-arrow { transform: rotate(90deg); }

.pb-model {
  font-size: 0.76rem;
  font-weight: bold;
  color: var(--c-text);
  letter-spacing: 0.02em;
  margin-top: 5px;
}

.pb-desc {
  font-size: 0.68rem;
  color: var(--c-text-dim);
  line-height: 1.55;
  margin-top: 2px;
}

.pb-factory {
  font-size: 0.66rem;
  color: var(--c-accent);
  letter-spacing: 0.03em;
  margin-top: 2px;
}

.pb-more {
  overflow: hidden;
  animation: pbMoreIn 0.3s ease;
}

@keyframes pbMoreIn {
  from { opacity: 0; transform: translateY(-4px); }
  to { opacity: 1; transform: translateY(0); }
}

.pb-more-in {
  margin-top: 6px;
  padding-top: 6px;
  border-top: 1px dashed var(--c-border);
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.pb-more-in .row {
  font-size: 0.68rem;
  color: var(--c-text-dim);
  line-height: 1.55;
}

.pb-more-in .row b { color: var(--c-text); font-weight: 600; }

.pb-go {
  align-self: flex-start;
  margin-top: 2px;
  font-size: 0.64rem;
  font-weight: bold;
  color: var(--c-panel);
  background: var(--c-accent);
  border: none;
  border-radius: 999px;
  padding: 2px 10px;
  cursor: pointer;
}

/* ---- ③ 系统监控全宽底（方案 A · 液舱柱：左三硬件 HUD 横条 + 右三液舱竖柱） ---- */
.sys-bar {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-top: 14px;
  padding: 12px 14px;
  border: 1px solid color-mix(in srgb, var(--c-accent) 28%, var(--c-border));
  border-radius: var(--r-radius);
  background: linear-gradient(150deg, color-mix(in srgb, var(--c-accent-deep) 55%, var(--c-panel)), var(--c-panel) 40%, var(--c-panel));
  box-shadow: var(--shadow-panel);
}

.sys-core {
  flex: 2.2;
  min-width: 0;
  display: flex;
  align-items: center;
  border-right: 1px solid color-mix(in srgb, var(--c-border) 70%, transparent);
  padding-right: 12px;
  gap: 4px;
}

.sys-item.hud {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 2px 10px;
}

.sys-item.hud .sys-ico {
  color: var(--c-accent);
  flex-shrink: 0;
}

.sys-item.hud .sys-name {
  font-size: 0.7rem;
  color: var(--c-text-dim);
  letter-spacing: 0.08em;
  flex-shrink: 0;
}

/* 纯大数字 + 颜色区分 */
.sys-item.hud .sys-val.big {
  flex: 1;
  font-size: 1.5rem;
  font-weight: 800;
  text-align: right;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.01em;
}

.sys-item.hud .sys-val.pw { color: #41d8a3; }
.sys-item.hud .sys-val.cu { color: #e8b64c; }
.sys-item.hud .sys-val.rm { color: #9aa7f0; }

/* 三液舱 */
.sys-tanks {
  flex: 1.4;
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: space-around;
  gap: 10px;
}

.tank {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.tank .tube {
  position: relative;
  width: 26px;
  height: 56px;
  border: 1px solid color-mix(in srgb, var(--c-border) 120%, transparent);
  border-radius: 7px;
  background: color-mix(in srgb, var(--c-panel-2) 80%, var(--c-panel));
  overflow: hidden;
}

.tank .tube .fill {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
}

.fill-cool { background: linear-gradient(180deg, #8ec8ff, #2f6fae); }
.fill-oil { background: linear-gradient(180deg, #ffd98e, #a87a1e); }
.fill-fluid { background: linear-gradient(180deg, #ffb0dd, #b84a8e); }

.fill-cool { background: linear-gradient(180deg, #8ec8ff, #2f6fae); }
.fill-oil { background: linear-gradient(180deg, #ffd98e, #a87a1e); }
.fill-fluid { background: linear-gradient(180deg, #ffb0dd, #b84a8e); }

.tank .tube .tl {
  position: absolute;
  left: 0;
  right: 0;
  height: 1px;
  background: color-mix(in srgb, var(--c-text-dim) 30%, transparent);
}

.tank .tube .l1 { top: 25%; }
.tank .tube .l2 { top: 50%; }
.tank .tube .l3 { top: 75%; }

.tank .tv {
  font-size: 0.8rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.tank .tn {
  font-size: 0.64rem;
  color: var(--c-text-dim);
  letter-spacing: 0.06em;
}

.f-cool { color: #5aa9e8; }
.f-oil { color: #e8b64c; }
.f-fluid { color: #e88ac4; }

/* ---- 手机端 ---- */
@media (max-width: 480px) {
  /* 人体图为底：全宽，详情悬浮其上 */
  .main-area {
    flex-direction: column;
    position: relative;
    gap: 0;
  }

  .body-col {
    width: 100%;
    height: auto;
    min-height: 420px;
    order: 1;
  }

  .body-col :deep(.body-svg) {
    max-width: 100%;
    width: 100%;
  }

  /* 详情区：不再占位，仅在选中时以悬浮层盖在人体图上 */
  .view-area {
    display: none;
    position: absolute;
    left: 50%;
    bottom: 10px;
    transform: translateX(-50%);
    width: 94%;
    max-height: 64%;
    z-index: 40;
    border-radius: var(--r-radius);
    background: color-mix(in srgb, var(--c-panel) 94%, transparent);
    box-shadow: 0 -10px 30px rgba(0, 0, 0, 0.5);
    height: auto;
  }

  .view-area.open {
    display: flex;
    flex-direction: column;
    overflow: hidden;
  }

  .view-main {
    overflow-y: auto;
    flex: 1;
    padding: 10px;
  }

  .view-close {
    display: block;
    align-self: flex-end;
    min-width: 34px;
    min-height: 34px;
    margin: 6px 6px 0 0;
    border: 1px solid var(--c-border);
    background: var(--c-panel-2);
    color: var(--c-text-dim);
    border-radius: calc(var(--r-radius) / 2);
    font-size: 0.85rem;
    cursor: pointer;
  }

  /* 顶部菜单：紧凑，尽量完整显示 */
  .menu-bar {
    flex-wrap: nowrap;
    gap: 3px;
    padding: 5px 6px;
  }

  .mb-item {
    min-height: 28px;
    padding: 0 8px;
    font-size: 0.68rem;
  }

  .mb-sep {
    font-size: 0.6rem;
    padding-left: 5px;
    margin-left: 0;
  }

  /* 四肢展开：换行多行小按钮，12 项完整可见 */
  .limb-bar {
    top: 44px;
    flex-wrap: wrap;
    overflow-x: visible;
    gap: 4px;
    padding: 6px 8px;
  }

  .limb-item {
    min-height: 26px;
    padding: 0 8px;
    font-size: 0.66rem;
  }

  /* 系统监控条：两行布局（电量大 + CPU/RAM 竖排右侧；液仓一行），不重叠 */
  .sys-bar {
    flex-direction: column;
    align-items: stretch;
    gap: 4px;
    padding: 6px 8px;
  }

  .sys-core {
    flex: none;
    display: grid;
    grid-template-columns: 1fr 1fr;
    grid-template-rows: auto auto;
    border-right: none;
    border-bottom: 1px solid color-mix(in srgb, var(--c-border) 70%, transparent);
    padding: 0 2px 4px;
    gap: 0 4px;
  }

  .sys-item.hud {
    padding: 2px 6px;
    gap: 6px;
  }

  /* 电量：左列竖跨两行，数字保持大 */
  .sys-item.hud:nth-child(1) {
    grid-column: 1;
    grid-row: 1 / span 2;
  }

  .sys-item.hud:nth-child(1) .sys-val.big {
    font-size: 1.5rem;
  }

  /* CPU / RAM：右列上下并列，数字缩小 */
  .sys-item.hud:nth-child(2) {
    grid-column: 2;
    grid-row: 1;
  }

  .sys-item.hud:nth-child(3) {
    grid-column: 2;
    grid-row: 2;
  }

  .sys-item.hud:nth-child(2) .sys-val.big,
  .sys-item.hud:nth-child(3) .sys-val.big {
    font-size: 0.95rem;
  }

  .sys-item.hud .sys-ico {
    width: 13px;
    height: 13px;
  }

  .sys-item.hud .sys-name {
    font-size: 0.62rem;
  }

  /* 液仓一行：紧凑小管 */
  .sys-tanks {
    flex: none;
    gap: 6px;
    padding: 2px 0;
  }

  .tank .tube {
    width: 22px;
    height: 44px;
    border-radius: 6px;
  }

  .tank .tv {
    font-size: 0.7rem;
  }

  .tank .tn {
    font-size: 0.58rem;
  }
}
