
.shop-panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* ============ Discourse 平台（独立主题变量） ============ */
.discourse-card {
  --brand: #ff3da6;
  --brand2: #8a4dff;
  --accent: #2dd4bf;
  --pg: #0d0a14;
  --p2: #1a0f22;
  --p3: #241536;
  --ln: #3a2247;
  --ln2: #5a2d66;
  --tx: #f3e8ff;
  --dim: #b79ac9;
  --dim2: #6f5a80;
  --shoot-a: #ff3d5a;
  --shoot-b: #c92a45;
  --live: #ff3d5a;
  --lb-bg: rgba(255, 61, 90, 0.12);
  --lb-bd: rgba(255, 61, 90, 0.35);
  --logo-glow: rgba(255, 61, 166, 0.4);
  --glow-a: rgba(255, 61, 166, 0.1);
  border: 1px solid var(--ln2);
  border-radius: 12px;
  background: linear-gradient(160deg, var(--p2) 0%, var(--pg) 100%);
  padding: 13px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  box-shadow: 0 4px 18px rgba(120, 50, 180, 0.25);
  position: relative;
  overflow: hidden;
  color: var(--tx);
  transition: background 0.3s, border-color 0.3s, color 0.3s;
}
.discourse-card::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(600px 160px at 50% -60px, var(--glow-a), transparent 70%);
}
.discourse-card[data-theme='cyan'] {
  --brand: #2dd4bf; --brand2: #3b82f6; --accent: #fbbf24;
  --pg: #060f14; --p2: #0b1a20; --p3: #102a33;
  --ln: #1d3d47; --ln2: #2b5f6d;
  --tx: #e6fbfa; --dim: #8fc7c4; --dim2: #4d7a78;
  --shoot-a: #22d3ee; --shoot-b: #0e7490;
  --live: #f43f5e;
  --lb-bg: rgba(244, 63, 94, 0.12); --lb-bd: rgba(244, 63, 94, 0.35);
  --logo-glow: rgba(45, 212, 191, 0.4); --glow-a: rgba(45, 212, 191, 0.1);
}
.discourse-card[data-theme='jade'] {
  --brand: #4ade80; --brand2: #16a34a; --accent: #22d3ee;
  --pg: #071109; --p2: #0c1a10; --p3: #12291a;
  --ln: #1f3d2a; --ln2: #2f6b46;
  --tx: #e9faef; --dim: #9cc9a8; --dim2: #57805f;
  --shoot-a: #22c55e; --shoot-b: #15803d;
  --live: #fb7185;
  --lb-bg: rgba(251, 113, 133, 0.12); --lb-bd: rgba(251, 113, 133, 0.35);
  --logo-glow: rgba(74, 222, 128, 0.4); --glow-a: rgba(74, 222, 128, 0.1);
}
.discourse-card[data-theme='amber'] {
  --brand: #fbbf24; --brand2: #f97316; --accent: #2dd4bf;
  --pg: #100c05; --p2: #1a1307; --p3: #2a200c;
  --ln: #3d3016; --ln2: #6b5420;
  --tx: #fdf5e6; --dim: #d4b98a; --dim2: #8a7448;
  --shoot-a: #f59e0b; --shoot-b: #b45309;
  --live: #f43f5e;
  --lb-bg: rgba(244, 63, 94, 0.12); --lb-bd: rgba(244, 63, 94, 0.35);
  --logo-glow: rgba(251, 191, 36, 0.4); --glow-a: rgba(251, 191, 36, 0.1);
}
.discourse-card[data-theme='crimson'] {
  --brand: #f43f5e; --brand2: #a855f7; --accent: #fbbf24;
  --pg: #120509; --p2: #1d0a11; --p3: #2d1020;
  --ln: #421522; --ln2: #6b2038;
  --tx: #fdeef2; --dim: #d08ba0; --dim2: #8a5266;
  --shoot-a: #f43f5e; --shoot-b: #be123c;
  --live: #f43f5e;
  --lb-bg: rgba(244, 63, 94, 0.14); --lb-bd: rgba(244, 63, 94, 0.4);
  --logo-glow: rgba(244, 63, 94, 0.4); --glow-a: rgba(244, 63, 94, 0.1);
}

.dc-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; flex-wrap: wrap; border-bottom: 1px solid rgba(255, 255, 255, 0.08); padding-bottom: 8px; position: relative; z-index: 1; }
.dc-brand { display: flex; align-items: center; gap: 8px; }
.dc-logo { width: 34px; height: 34px; border-radius: 8px; background: rgba(255, 255, 255, 0.05); border: 1px solid var(--brand); display: flex; align-items: center; justify-content: center; box-shadow: 0 0 14px var(--logo-glow); }
.dc-name { font-weight: bold; font-size: 0.95rem; color: var(--tx); letter-spacing: 0.04em; }
.dc-tag { font-size: 0.66rem; color: var(--dim); border: 1px solid var(--ln2); border-radius: 8px; padding: 1px 8px; }
.dc-actions { display: flex; align-items: center; gap: 7px; flex-wrap: wrap; }

.dc-btn { min-height: 36px; padding: 0 13px; border-radius: 999px; font-weight: bold; font-size: 0.76rem; cursor: pointer; display: inline-flex; align-items: center; gap: 5px; border: none; font-family: inherit; }
.dc-btn-shoot { background: linear-gradient(135deg, var(--shoot-a), var(--shoot-b)); color: #fff; box-shadow: 0 2px 10px var(--lb-bd); }
.dc-btn-live { border: 1px solid var(--live); background: var(--lb-bg); color: #ffb3c2; }
.dc-btn-ghost { border: 1px solid var(--ln2); background: transparent; color: var(--dim); }
.dc-btn-sub { border: 1px solid var(--ln2); background: transparent; color: var(--dim); }
.dc-btn-sub:hover { color: var(--brand); border-color: var(--brand); }
.dc-btn:active { transform: translateY(2px) scale(0.98); }

.rec-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--live); box-shadow: 0 0 6px var(--live); }
.rec-dot.off { background: #5c6675; box-shadow: none; }
.rec-dot.red { animation: dcblink 1s infinite; }
@keyframes dcblink { 50% { opacity: 0.25; } }

/* 频道导航 */
.dc-nav { display: flex; gap: 4px; border-bottom: 1px solid rgba(255, 255, 255, 0.08); padding-bottom: 6px; position: relative; z-index: 1; flex-wrap: wrap; }
.dc-nav-item { min-height: 30px; padding: 0 13px; border: none; background: transparent; color: var(--dim); font-size: 0.78rem; cursor: pointer; border-radius: 6px; }
.dc-nav-item.on { color: var(--brand); background: rgba(255, 255, 255, 0.08); font-weight: bold; }

/* 拍摄状态横幅 */
.rec-bar { position: relative; z-index: 1; display: flex; align-items: center; gap: 10px; border: 1px solid var(--live); border-radius: 10px; background: var(--lb-bg); padding: 8px 12px; }
.rec-txt { flex: none; }
.rec-t { font-size: 0.78rem; font-weight: bold; color: var(--tx); }
.rec-s { font-size: 0.64rem; color: var(--dim); margin-top: 2px; }
.rec-timer { font-size: 0.72rem; color: var(--live); font-weight: bold; font-variant-numeric: tabular-nums; }
.rec-tip { flex: 1; font-size: 0.62rem; color: var(--dim); }

.dc-view { display: flex; flex-direction: column; gap: 10px; position: relative; z-index: 1; }

.sec-t { font-size: 0.7rem; font-weight: bold; color: var(--dim); letter-spacing: 0.1em; padding-top: 6px; border-bottom: 1px dashed var(--ln); padding-bottom: 5px; display: flex; justify-content: space-between; align-items: center; }
.sec-t em { font-style: normal; font-size: 0.6rem; color: var(--dim2); }

/* 创作者数据条 */
.dc-creator { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; }
.dc-cstat { display: flex; flex-direction: column; align-items: center; padding: 7px 4px; border-radius: 8px; background: rgba(255, 255, 255, 0.05); border: 1px solid rgba(255, 255, 255, 0.07); }
.dc-cstat b { color: var(--brand); font-size: 0.96rem; line-height: 1.2; }
.dc-cstat em { font-style: normal; font-size: 0.6rem; color: var(--dim); line-height: 1.2; }

/* 搜索 */
.dc-search { position: relative; }
.dc-search input { width: 100%; min-height: 38px; padding: 0 34px 0 12px; border: 1px solid var(--ln); border-radius: 999px; background: var(--pg); color: var(--tx); font-size: 0.76rem; font-family: inherit; }
.dc-search input::placeholder { color: var(--dim2); }
.dc-search-ico { position: absolute; right: 12px; top: 50%; transform: translateY(-50%); color: var(--dim); font-size: 0.9rem; pointer-events: none; }

/* 直播横幅（今日直播） */
.dc-livebar-a { display: flex; align-items: center; gap: 10px; border: 1px solid var(--lb-bd); border-radius: 10px; background: linear-gradient(120deg, var(--lb-bg), rgba(138, 77, 255, 0.08)); padding: 9px 12px; }
.lb-thumb { width: 56px; height: 38px; border-radius: 6px; background: linear-gradient(135deg, #4a120e, #7d2317); display: flex; align-items: center; justify-content: center; }
.lb-thumb b { font-size: 0.6rem; color: #fff; background: var(--live); border-radius: 4px; padding: 1px 6px; }
.lb-meta { flex: 1; min-width: 0; }
.lb-title { font-size: 0.78rem; font-weight: bold; color: var(--tx); }
.lb-sub { font-size: 0.64rem; color: var(--dim); margin-top: 2px; }
.lb-view { font-size: 0.66rem; color: var(--live); font-weight: bold; white-space: nowrap; }

/* 信息流卡片 */
.dc-feed { display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 9px; }
.fcard { border: 1px solid var(--ln); border-radius: 9px; overflow: hidden; background: var(--p2); cursor: default; transition: border-color 0.15s, transform 0.15s; }
.fcard:hover { border-color: var(--ln2); transform: translateY(-2px); }
.fc-thumb { height: 82px; position: relative; }
.fc-thumb .fc-t { position: absolute; right: 6px; top: 6px; font-size: 0.6rem; color: #fff; background: rgba(0, 0, 0, 0.55); border-radius: 6px; padding: 1px 7px; }
.fc-thumb .fc-p { position: absolute; left: 7px; bottom: 6px; font-size: 0.62rem; color: rgba(255, 255, 255, 0.92); text-shadow: 0 1px 3px rgba(0, 0, 0, 0.6); }
.fc-1 { background: linear-gradient(135deg, #4a120e, #7d2317); }
.fc-2 { background: linear-gradient(135deg, #0f3a36, #17594f); }
.fc-3 { background: linear-gradient(135deg, #1d2b66, #33489b); }
.fc-4 { background: linear-gradient(135deg, #3d1030, #6b1a52); }
.fc-5 { background: linear-gradient(135deg, #33303f, #544f66); }
.fc-body { padding: 7px 9px; }
.fc-title { font-size: 0.76rem; font-weight: bold; color: var(--tx); line-height: 1.35; min-height: 2.1em; }
.fc-line { display: flex; align-items: center; justify-content: space-between; gap: 4px; font-size: 0.62rem; color: var(--dim); margin-top: 4px; }
.fc-line .u { color: var(--brand); }
.fc-like { color: var(--dim2); }

/* 在更视频 */
.dc-videos { display: grid; grid-template-columns: repeat(auto-fill, minmax(170px, 1fr)); gap: 8px; }
.dc-video { border: 1px solid var(--ln); border-radius: 8px; overflow: hidden; background: var(--p2); }
.dc-thumb { height: 74px; display: flex; align-items: center; justify-content: center; position: relative; background: linear-gradient(135deg, var(--p3), var(--ln)); }
.v-常规 .dc-thumb { background: linear-gradient(135deg, #0f3a36, #17594f); }
.v-擦边 .dc-thumb { background: linear-gradient(135deg, #4a3312, #7a5520); }
.v-NSFW .dc-thumb { background: linear-gradient(135deg, #3d1030, #6b1a52); }
.v-机损 .dc-thumb { background: linear-gradient(135deg, #4a120e, #7d2317); }
.v-自毁 .dc-thumb { background: linear-gradient(135deg, #2a0d1d, #4d1420); }
.dc-play { width: 34px; height: 34px; border-radius: 50%; background: rgba(255, 255, 255, 0.92); color: #1a0f22; display: flex; align-items: center; justify-content: center; font-size: 0.72rem; padding-left: 2px; }
.dc-type { position: absolute; right: 6px; bottom: 6px; font-size: 0.62rem; color: #fff; background: rgba(0, 0, 0, 0.5); border-radius: 6px; padding: 1px 7px; }
.dc-meta { padding: 7px 9px; display: flex; flex-direction: column; gap: 3px; }
.dc-title { font-size: 0.8rem; font-weight: bold; color: var(--tx); }
.dc-line { font-size: 0.68rem; color: var(--dim); }
.dc-empty { font-size: 0.76rem; color: var(--dim); text-align: center; padding: 12px; border: 1px dashed var(--ln); border-radius: 8px; }

/* 工作室 */
.dc-studio { display: grid; grid-template-columns: 1.7fr 1fr; gap: 10px; }
.st-col { display: flex; flex-direction: column; gap: 10px; min-width: 0; }
.st-panel { border: 1px solid var(--ln); border-radius: 10px; background: var(--p2); overflow: hidden; }
.st-head { display: flex; align-items: center; justify-content: space-between; padding: 8px 11px; border-bottom: 1px solid var(--ln); font-size: 0.74rem; font-weight: bold; color: var(--brand); }
.st-head em { font-style: normal; font-size: 0.6rem; color: var(--dim2); font-weight: normal; }
.st-row { display: flex; align-items: center; gap: 9px; padding: 8px 11px; border-bottom: 1px solid rgba(255, 255, 255, 0.05); }
.st-row:last-child { border-bottom: none; }
.st-thumb { width: 64px; height: 40px; border-radius: 6px; flex: none; }
.st-meta { flex: 1; min-width: 0; }
.st-t { font-size: 0.74rem; font-weight: bold; color: var(--tx); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.st-s { font-size: 0.62rem; color: var(--dim); margin-top: 2px; }
.st-stat { font-size: 0.64rem; color: var(--dim2); white-space: nowrap; }
.st-tag { font-size: 0.6rem; border-radius: 6px; padding: 1px 7px; white-space: nowrap; }
.st-正在 { color: var(--accent); border: 1px solid rgba(45, 212, 191, 0.4); background: rgba(45, 212, 191, 0.1); }
.st-完结 { color: var(--dim2); border: 1px solid var(--ln); background: transparent; }
.st-empty { font-size: 0.68rem; color: var(--dim2); text-align: center; padding: 14px 0; }
.st-stat-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 6px; padding: 10px; }
.st-stat-cell { border: 1px solid var(--ln); border-radius: 8px; background: var(--pg); padding: 8px; }
.st-stat-cell b { display: block; font-size: 0.98rem; color: var(--brand); }
.st-stat-cell span { font-size: 0.6rem; color: var(--dim); }
.st-chart { padding: 10px; }
.st-bar { height: 8px; border-radius: 4px; background: rgba(255, 255, 255, 0.06); margin: 12px 0 6px; overflow: hidden; }
.st-bar i { display: block; height: 100%; border-radius: 4px; background: linear-gradient(90deg, var(--brand), var(--brand2)); }
.st-cl { display: flex; justify-content: space-between; font-size: 0.6rem; color: var(--dim2); }
.st-note { font-size: 0.6rem; color: var(--dim2); margin-top: 6px; }

/* 素材库 + 编辑 */
.mat-layout { display: grid; grid-template-columns: 240px 1fr; gap: 10px; }
.mat-list { display: flex; flex-direction: column; gap: 8px; }
.mat-card { border: 1px solid var(--ln); border-radius: 9px; overflow: hidden; background: var(--p2); cursor: pointer; transition: border-color 0.15s; }
.mat-card:hover { border-color: var(--ln2); }
.mat-card.on { border-color: var(--brand); box-shadow: 0 0 0 1px var(--brand); }
.mt-thumb { height: 56px; position: relative; }
.mt-thumb .dur { position: absolute; right: 6px; bottom: 5px; font-size: 0.58rem; color: #fff; background: rgba(0, 0, 0, 0.55); border-radius: 5px; padding: 0 6px; }
.mt-body { padding: 6px 9px; }
.mt-t { font-size: 0.7rem; font-weight: bold; color: var(--tx); }
.mt-s { font-size: 0.6rem; color: var(--dim); margin-top: 2px; }
.mat-empty { font-size: 0.72rem; color: var(--dim2); text-align: center; padding: 20px 8px; border: 1px dashed var(--ln); border-radius: 9px; line-height: 1.7; }
.mat-empty span { font-size: 0.62rem; }
.edit-panel { border: 1px solid var(--ln); border-radius: 10px; background: var(--p2); padding: 11px; display: flex; flex-direction: column; gap: 10px; }
.ep-row { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.ep-label { font-size: 0.66rem; color: var(--dim); width: 64px; flex: none; }
.ep-input { flex: 1; min-width: 150px; min-height: 32px; padding: 0 10px; border: 1px solid var(--ln); border-radius: 8px; background: var(--pg); color: var(--tx); font-size: 0.74rem; font-family: inherit; }
.ep-input::placeholder { color: var(--dim2); }
.ep-input:disabled { opacity: 0.5; }
.chips { display: flex; gap: 6px; flex-wrap: wrap; }
.chip { min-height: 30px; padding: 0 12px; border: 1px solid var(--ln2); border-radius: 999px; background: transparent; color: var(--dim); font-size: 0.7rem; cursor: pointer; font-family: inherit; }
.chip.on { border-color: var(--brand); color: var(--brand); background: rgba(255, 255, 255, 0.06); font-weight: bold; }
.pv-grid { display: flex; gap: 8px; align-items: flex-start; flex-wrap: wrap; }
.cover-box { width: 150px; height: 84px; border-radius: 8px; display: flex; align-items: center; justify-content: center; font-size: 0.62rem; color: rgba(255, 255, 255, 0.85); border: 1px solid var(--ln); }
.pv-side { display: flex; flex-direction: column; gap: 6px; }
.pr-card { flex: 1; min-width: 150px; border: 1px solid var(--ln); border-radius: 9px; background: var(--pg); padding: 9px; }
.pr-l { display: flex; justify-content: space-between; font-size: 0.64rem; color: var(--dim); margin: 4px 0; }
.pr-l b { color: var(--tx); }
.pr-l b.up { color: var(--accent); }
.pr-note { font-size: 0.6rem; color: var(--dim2); line-height: 1.6; }

/* 直播设置 */
.live-set { display: grid; grid-template-columns: 1.4fr 1fr; gap: 10px; }
.lv-body { padding: 11px; display: flex; flex-direction: column; gap: 10px; }
.lv-row { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.lv-lb { font-size: 0.6rem; color: var(--dim); }
.lv-val { font-size: 1rem; font-weight: bold; color: var(--brand); }
.lv-val.sm { font-size: 0.78rem; color: var(--dim); }
.lv-actions { display: flex; gap: 8px; }
.lv-hist { padding: 10px; display: flex; flex-direction: column; gap: 8px; }
.lv-rec { border: 1px solid var(--ln); border-radius: 9px; background: var(--p2); padding: 9px; display: flex; flex-direction: column; gap: 4px; }
.lv-t { font-size: 0.74rem; font-weight: bold; color: var(--tx); }
.lv-s { font-size: 0.62rem; color: var(--dim); }

/* 直播悬浮窗（独立于页面） */
.lv-float {
  position: fixed;
  right: 16px;
  bottom: 16px;
  width: 300px;
  z-index: 99;
  border: 1px solid #ff3d5a;
  border-radius: 12px;
  overflow: hidden;
  background: linear-gradient(165deg, #1d0a10, #120509);
  color: #fdeef2;
  box-shadow: 0 10px 34px rgba(0, 0, 0, 0.6), 0 0 0 1px rgba(255, 61, 90, 0.25);
  display: none;
  flex-direction: column;
}
.lv-float.open { display: flex; }
.lvf-head { display: flex; align-items: center; gap: 9px; padding: 9px 12px; border-bottom: 1px solid rgba(255, 255, 255, 0.1); background: rgba(255, 255, 255, 0.03); }
.lvf-title { flex: 1; min-width: 0; }
.lvf-t { font-size: 0.78rem; font-weight: bold; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.lvf-s { font-size: 0.6rem; color: #d08ba0; margin-top: 2px; }
.lvf-view { font-size: 0.72rem; color: #ffb3c2; font-weight: bold; white-space: nowrap; }
.lvf-stage { height: 118px; background: radial-gradient(240px 90px at 50% 0%, rgba(255, 61, 90, 0.14), transparent 75%), #12060a; display: flex; align-items: center; justify-content: center; position: relative; padding: 8px 10px; }
.lvf-chart { width: 100%; height: 100%; }
.lvf-chart-label { position: absolute; left: 10px; bottom: 6px; font-size: 0.58rem; color: #b06a7c; letter-spacing: 0.06em; }
.lvf-peak { position: absolute; left: 10px; top: 6px; font-size: 0.6rem; color: #ffb3c2; }
.lvf-timer { position: absolute; right: 8px; top: 6px; font-size: 0.62rem; color: #fff; background: rgba(0, 0, 0, 0.5); border-radius: 6px; padding: 1px 8px; font-variant-numeric: tabular-nums; }
.lvf-body { height: 150px; overflow: hidden; padding: 8px 12px; display: flex; flex-direction: column; gap: 5px; }
.lvf-dm { font-size: 0.64rem; color: #f1d9df; line-height: 1.5; animation: dcdmIn 0.6s; }
.lvf-dm b { color: #ff3da6; font-weight: bold; }
@keyframes dcdmIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }
.lvf-foot { display: flex; align-items: center; justify-content: space-between; padding: 8px 12px; border-top: 1px solid rgba(255, 255, 255, 0.1); background: rgba(255, 255, 255, 0.03); }
.lvf-stat { font-size: 0.64rem; color: #d08ba0; }
.lvf-end { min-height: 30px; padding: 0 14px; border: 1px solid #ff3d5a; border-radius: 999px; background: rgba(255, 61, 90, 0.16); color: #ffb3c2; font-weight: bold; font-size: 0.7rem; cursor: pointer; font-family: inherit; }

/* 设置弹层 */
.modal-mask { position: fixed; inset: 0; background: rgba(4, 5, 10, 0.7); display: flex; align-items: center; justify-content: center; z-index: 120; }
.modal { width: 340px; max-width: 92vw; border: 1px solid #3a2247; border-radius: 14px; background: #12101d; padding: 16px; color: #e9e2f3; box-shadow: 0 14px 44px rgba(0, 0, 0, 0.6); }
.modal h3 { font-size: 0.86rem; margin-bottom: 12px; color: #ff3da6; }
.theme-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 8px; }
.th { border: 2px solid rgba(255, 255, 255, 0.18); border-radius: 10px; height: 56px; cursor: pointer; display: flex; align-items: center; justify-content: center; font-size: 0.6rem; color: #fff; transition: transform 0.12s; }
.th:hover { transform: scale(1.06); }
.th.on { border-color: #fff; box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.3); }
.th-plum { background: linear-gradient(135deg, #ff3da6, #8a4dff); }
.th-cyan { background: linear-gradient(135deg, #2dd4bf, #3b82f6); }
.th-jade { background: linear-gradient(135deg, #4ade80, #16a34a); }
.th-amber { background: linear-gradient(135deg, #fbbf24, #f97316); }
.th-crimson { background: linear-gradient(135deg, #f43f5e, #a855f7); }
.m-note { font-size: 0.62rem; color: #9a8fb0; margin-top: 10px; line-height: 1.6; }
.m-foot { display: flex; justify-content: flex-end; margin-top: 12px; }

/* 底部品牌装饰条 */
.dc-footer { display: flex; align-items: center; gap: 10px; color: var(--dim2); font-size: 0.62rem; letter-spacing: 0.08em; }
.dc-foot-line { flex: 1; height: 1px; background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.25), transparent); }

.tip { background: var(--c-panel); border: 1px solid var(--c-border-light); border-left: 3px solid var(--c-accent); padding: 8px 10px; font-size: 0.76rem; line-height: 1.6; color: var(--c-text); }

@media (max-width: 600px) {
  .dc-studio, .live-set { grid-template-columns: 1fr; }
  .mat-layout { grid-template-columns: 1fr; }
  .dc-creator { grid-template-columns: repeat(2, 1fr); }
  .lv-float { width: 100%; right: 0; bottom: 0; border-radius: 14px 14px 0 0; }
}
