
.settle-mask {
  position: fixed;
  inset: 0;
  z-index: 200;
  background: rgba(4, 6, 10, 0.72);
  backdrop-filter: blur(2px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.settle-modal {
  position: relative;
  width: 100%;
  max-width: 460px;
  max-height: 84vh;
  display: flex;
  flex-direction: column;
  background: var(--c-panel-2);
  border: 1px solid var(--c-border-light);
  border-radius: var(--r-radius);
  box-shadow: 0 18px 60px rgba(0, 0, 0, 0.6);
  overflow: hidden;
}

/* 汇总数字：等宽数字，滚动不抖 */
.num {
  font-variant-numeric: tabular-nums;
}

/* 明细条目：逐条浮现（延时由脚本按行序设置） */
.settle-modal .sm-row {
  opacity: 0;
  animation: smRowFade 0.4s ease-out forwards;
}

@keyframes smRowFade {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

/* 头部 */
.sm-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  padding: 12px 14px 10px;
  border-bottom: 1px solid var(--c-border);
}

.sm-title {
  font-size: 0.98rem;
  font-weight: bold;
  color: var(--c-accent);
  letter-spacing: 0.03em;
}

.sm-sub {
  font-size: 0.68rem;
  color: var(--c-text-dim);
  margin-top: 2px;
}

.sm-x {
  flex: none;
  min-width: 30px;
  min-height: 30px;
  border: 1px solid var(--c-border);
  background: var(--c-panel-3);
  color: var(--c-text-dim);
  border-radius: 6px;
  cursor: pointer;
  font-size: 0.8rem;
}

.sm-x:hover {
  color: var(--c-text);
  border-color: var(--c-border-light);
}

/* 汇总条 */
.sm-summary {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--c-border);
  background: var(--c-panel);
}

.sm-stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  padding: 6px 2px;
  border-radius: 8px;
  background: var(--c-panel-2);
  border: 1px solid var(--c-border);
}

.sm-stat.neg .sm-stat-v {
  color: var(--c-danger);
}

.sm-stat-v {
  font-size: 0.82rem;
  font-weight: bold;
  color: var(--c-accent);
}

.sm-stat-v b {
  font-weight: bold;
}

.sm-stat-l {
  font-size: 0.6rem;
  color: var(--c-text-dim);
}

/* 明细 */
.sm-body {
  flex: 1;
  overflow-y: auto;
  padding: 4px 14px 8px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.sm-sec {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.sm-sec-head {
  font-size: 0.7rem;
  font-weight: bold;
  color: var(--c-text-dim);
  letter-spacing: 0.06em;
  padding-top: 6px;
  border-bottom: 1px dashed var(--c-border);
  padding-bottom: 4px;
}

.sm-sec-sub {
  font-style: normal;
  font-size: 0.62rem;
  color: var(--c-text-dim);
  opacity: 0.8;
  font-weight: normal;
  letter-spacing: normal;
  margin-left: 6px;
}

.sm-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  font-size: 0.76rem;
  padding: 3px 2px;
}

.sm-row-name {
  font-weight: bold;
  color: var(--c-text);
}

.sm-row-tags {
  display: flex;
  gap: 5px;
  flex-wrap: wrap;
}

.tag {
  font-size: 0.66rem;
  border-radius: 6px;
  padding: 1px 7px;
}

.tag-money {
  color: var(--c-accent);
  border: 1px solid color-mix(in srgb, var(--c-accent) 45%, transparent);
  background: color-mix(in srgb, var(--c-accent) 10%, transparent);
}

.tag-fans {
  color: var(--c-info);
  border: 1px solid color-mix(in srgb, var(--c-info) 45%, transparent);
  background: color-mix(in srgb, var(--c-info) 10%, transparent);
}

.tag-fame {
  color: var(--c-warn);
  border: 1px solid color-mix(in srgb, var(--c-warn) 45%, transparent);
  background: color-mix(in srgb, var(--c-warn) 10%, transparent);
}

.sm-done {
  font-size: 0.62rem;
  color: var(--c-text-dim);
  border: 1px dashed var(--c-border);
  border-radius: 6px;
  padding: 1px 6px;
}

.sm-row-note {
  color: var(--c-text-dim);
}

.sm-row.warn .sm-row-note {
  color: var(--c-danger);
  font-weight: bold;
}

.sm-empty {
  font-size: 0.76rem;
  color: var(--c-text-dim);
  text-align: center;
  padding: 18px 0;
  line-height: 1.6;
}

/* 底部按钮 */
.sm-ok {
  flex: none;
  margin: 0 14px 14px;
  min-height: 42px;
  border: none;
  border-radius: var(--r-radius);
  background: var(--c-accent);
  color: #06201c;
  font-weight: bold;
  font-size: 0.86rem;
  cursor: pointer;
  box-shadow: 0 2px 0 rgba(0, 0, 0, 0.25);
}

.sm-ok:active {
  transform: translateY(2px) scale(0.99);
  box-shadow: none;
}

@media (max-width: 480px) {
  .sm-summary {
    grid-template-columns: repeat(2, 1fr);
  }
}
