
.module-panel {
  border: 1px solid var(--c-border);
  border-radius: var(--r-radius);
  background: var(--c-panel);
  padding: 10px;
  flex: 1;
  min-width: 0;
}

.head {
  font-size: 0.86rem;
  font-weight: bold;
  color: var(--c-accent);
  border-bottom: 1px solid var(--c-border);
  padding-bottom: 5px;
  margin-bottom: 6px;
}

.module-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 6px;
  border-radius: var(--r-radius);
  cursor: pointer;
}

.module-row:hover {
  background: var(--c-panel-2);
}

.hint {
  margin-top: 6px;
  font-size: 0.68rem;
  color: var(--c-text-dim);
  text-align: center;
}

.m-name {
  width: 70px;
  flex-shrink: 0;
  color: var(--c-text);
  font-size: 0.76rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.track {
  flex: 1;
  height: 8px;
  border: 1px solid var(--c-border);
  background: var(--c-bg);
  overflow: hidden;
  border-radius: calc(var(--r-radius) / 2);
}

.fill {
  height: 100%;
  transition: width 0.25s ease;
}

.fill.low {
  animation: bd-blink 0.9s step-end infinite;
}

.m-val {
  width: 62px;
  text-align: right;
  color: var(--c-text-dim);
  font-size: 0.72rem;
  flex-shrink: 0;
}

.m-val.val-low {
  color: var(--c-danger);
  font-weight: bold;
}
