
/* 亚马送：拟真电商（红橙 + 白卡片 + 搜索栏），独立于控制台与 Discourse */
.shop-platform {
  display: flex;
  flex-direction: column;
  border: 1px solid #e6b8a0;
  border-radius: 10px;
  padding: 0;
  background: linear-gradient(180deg, #fff7f2, #ffefe6);
  box-shadow: 0 3px 14px rgba(180, 80, 30, 0.18);
  color: #3a2a1e;
  font-family: 'Microsoft YaHei', 'PingFang SC', sans-serif;
  position: relative;
  overflow: hidden;
  min-height: 320px;
}

/* 滚动层：亚马送内容（头部/商品/购物车）在此内部滚动；广告位于本层之外，固定不动 */
.shop-scroll {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 10px;
  box-sizing: border-box;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: #f0b492 transparent;
}

.sp-head {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.sp-brand {
  display: flex;
  align-items: center;
  gap: 10px;
}

.sp-logo {
  width: 132px;
  height: 40px;
  display: block;
  filter: drop-shadow(0 2px 6px rgba(232, 68, 46, 0.35));
}

.sp-name {
  font-weight: bold;
  font-size: 1.15rem;
  color: #e8442e;
  letter-spacing: 0.05em;
}

.sp-slogan {
  font-size: 0.68rem;
  color: #b0704f;
}

.sp-search {
  display: flex;
  gap: 6px;
}

.sp-search input {
  flex: 1;
  min-height: 40px;
  padding: 0 14px;
  border: 1.5px solid #e8442e;
  border-radius: 999px;
  background: #fff;
  color: #3a2a1e;
  font-size: 0.8rem;
  font-family: inherit;
}

.sp-search-btn {
  min-height: 40px;
  padding: 0 20px;
  border: none;
  border-radius: 999px;
  background: linear-gradient(135deg, #ff6a00, #e8442e);
  color: #fff;
  font-weight: bold;
  font-size: 0.82rem;
  cursor: pointer;
}

.sp-banner {
  display: flex;
  align-items: baseline;
  gap: 10px;
  background: linear-gradient(135deg, #ffe3d3, #ffd0bd);
  border: 1px solid #f0b492;
  border-radius: 8px;
  padding: 8px 12px;
}

.banner-main {
  font-weight: bold;
  color: #e8442e;
  font-size: 0.9rem;
}

.banner-sub {
  font-size: 0.7rem;
  color: #a05a38;
}

.cats {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.cat {
  min-height: 40px;
  padding: 0 12px;
  border: 1px solid #e8c4ae;
  background: #fff;
  color: #8a5a3c;
  font-size: 0.78rem;
  cursor: pointer;
  border-radius: 8px;
}

.cat.active {
  border-color: #e8442e;
  color: #fff;
  background: #e8442e;
  font-weight: bold;
}

.goods-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 8px;
}

.goods-card {
  border: 1px solid #eed4c2;
  border-radius: 8px;
  background: #fff;
  padding: 7px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  box-shadow: 0 1px 4px rgba(150, 80, 40, 0.08);
  cursor: pointer;
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}

.goods-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(180, 80, 30, 0.16);
}

.goods-card.exp {
  grid-column: span 2;
  grid-row: span 2;
  position: relative;
  padding: 10px;
  z-index: 2;
}

.g-collapse {
  position: absolute;
  top: 6px;
  right: 6px;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  border: 1px solid #e8c4ae;
  background: #fff;
  color: #a05a38;
  font-size: 0.72rem;
  cursor: pointer;
}

.g-pic {
  height: 52px;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  border: 1px solid rgba(200, 120, 60, 0.25);
}

.g-pic-big {
  height: 96px;
  font-size: 2.4rem;
}

.g-cat {
  align-self: flex-start;
  font-size: 0.6rem;
  color: #e8442e;
  border: 1px solid #f2c4b2;
  border-radius: 6px;
  padding: 0 6px;
}

.g-name {
  font-weight: bold;
  font-size: 0.84rem;
  color: #3a2a1e;
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
}

.g-name-big {
  font-size: 1rem;
}

.sp-tag {
  font-size: 0.56rem;
  padding: 1px 6px;
  border-radius: 4px;
  vertical-align: middle;
}

.sp-tag.hot {
  background: #ffb020;
  color: #5a3200;
}

.sp-tag.new {
  background: #ff3b30;
  color: #fff;
}

.sp-tag.month {
  background: #8a5ae8;
  color: #fff;
}

.g-desc {
  font-size: 0.7rem;
  color: #96755c;
  line-height: 1.4;
  flex: 1;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.g-desc-big {
  -webkit-line-clamp: unset;
  font-size: 0.76rem;
}

.g-meta {
  display: flex;
  flex-direction: column;
  gap: 3px;
  font-size: 0.66rem;
  color: #6a4a34;
  border-top: 1px dashed #eed4c2;
  padding-top: 6px;
  margin-top: 2px;
}

.g-meta i {
  display: inline-block;
  width: 52px;
  color: #b0704f;
  font-style: normal;
}

.g-price {
  display: flex;
  align-items: baseline;
  gap: 3px;
}

.gp-symbol {
  color: #e8442e;
  font-size: 0.68rem;
}

.gp-num {
  color: #e8442e;
  font-weight: bold;
  font-size: 1rem;
}

.gp-origin {
  color: #b8a08e;
  font-size: 0.58rem;
  text-decoration: line-through;
}

.gp-unit {
  color: #96755c;
  font-size: 0.66rem;
}

.g-row {
  display: flex;
  align-items: center;
  gap: 5px;
}

.g-sales {
  font-size: 0.58rem;
  color: #b8a08e;
}

.g-ops {
  display: flex;
  gap: 6px;
}

.g-ops .g-qk {
  min-height: 40px;
  padding: 0 12px;
  border: 1px solid #e8c4ae;
  background: #fff;
  color: #e8442e;
  font-size: 0.74rem;
  font-weight: bold;
  border-radius: 8px;
  cursor: pointer;
}

.g-add {
  min-height: 40px;
  border: 1px solid #ff6a00;
  background: linear-gradient(135deg, #ff6a00, #e8442e);
  color: #fff;
  font-size: 0.78rem;
  font-weight: bold;
  cursor: pointer;
  border-radius: 8px;
  flex: 1;
}

.g-add:active {
  transform: translateY(1px);
}

.cart-bar {
  border: 1px solid #e8c4ae;
  border-radius: 8px;
  background: #fff;
  overflow: hidden;
}

.cart-head {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  padding: 6px 8px;
}

.cart-toggle {
  min-height: 40px;
  padding: 0 14px;
  border: 1px solid #ff6a00;
  background: #fff3ec;
  color: #e8442e;
  font-weight: bold;
  font-size: 0.82rem;
  cursor: pointer;
  border-radius: 8px;
}

.ship-opt {
  display: flex;
  gap: 10px;
  font-size: 0.74rem;
  color: #6a4a34;
}

.ship-opt label {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  cursor: pointer;
}

.cart-total {
  margin-left: auto;
  font-size: 0.82rem;
  color: #6a4a34;
}

.cart-total b {
  color: #e8442e;
  font-size: 0.95rem;
}

.cart-body {
  border-top: 1px solid #eed4c2;
  padding: 8px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.cart-empty {
  color: #96755c;
  font-size: 0.76rem;
  text-align: center;
  padding: 10px;
}

.cart-row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.78rem;
  color: #3a2a1e;
}

.c-name {
  flex: 1;
}

.c-qty {
  color: #96755c;
}

.c-price {
  min-width: 60px;
  text-align: right;
  color: #e8442e;
  font-weight: bold;
}

.c-del {
  width: 30px;
  height: 30px;
  border: 1px solid #eed4c2;
  background: #fff;
  color: #96755c;
  cursor: pointer;
  border-radius: 6px;
}

.checkout {
  min-height: 46px;
  border: none;
  background: linear-gradient(135deg, #ff6a00, #e8442e);
  color: #fff;
  font-weight: bold;
  font-size: 0.86rem;
  cursor: pointer;
  border-radius: 8px;
}

.checkout:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.cart-note {
  font-size: 0.68rem;
  color: #96755c;
  line-height: 1.5;
}

.tip {
  background: #fff;
  border: 1px solid #eed4c2;
  border-left: 3px solid #e8442e;
  padding: 8px 10px;
  font-size: 0.76rem;
  line-height: 1.6;
  color: #4a3222;
}

/* ===== 整图广告：在亚马送 UI 滚动层外面一层（absolute 相对组件根），内部滚动不影响广告位置 ===== */
.ad {
  position: absolute;
  z-index: 90;
  cursor: pointer;
}

.ad img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  pointer-events: none;
}

.ad .realx {
  position: absolute;
  top: 5px;
  right: 8px;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: none;
  background: rgba(0, 0, 0, 0.5);
  color: #fff;
  font-size: 0.78rem;
  line-height: 1;
  cursor: pointer;
  z-index: 3;
}

/* 左下折叠按钮：点击弹出「今天不再显示」 */
.ad-fold {
  position: absolute;
  left: 5px;
  bottom: 5px;
  z-index: 4;
}

.ad-fold .fold-btn {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: none;
  background: rgba(0, 0, 0, 0.5);
  color: #fff;
  font-size: 0.7rem;
  line-height: 1;
  cursor: pointer;
}

.ad-fold .fold-pop {
  position: absolute;
  left: 0;
  bottom: 26px;
  background: #fff;
  border: 1px solid #e8c4ae;
  border-radius: 8px;
  box-shadow: 0 6px 18px rgba(120, 60, 20, 0.25);
  white-space: nowrap;
  overflow: hidden;
}

.ad-fold .fold-pop button {
  display: block;
  width: 100%;
  min-height: 36px;
  padding: 0 14px;
  border: none;
  background: #fff;
  color: #3a2a1e;
  font-size: 0.74rem;
  cursor: pointer;
  text-align: center;
}

.ad-fold .fold-pop button:hover {
  background: #fff3ec;
  color: #e8442e;
}

/* 固定角落定位：广告在滚动层之外，内部怎么滚都不影响其位置 */
.ad.br {
  bottom: 12px;
  right: 12px;
  width: 150px;
  height: 202px;
}

.ad.bl {
  bottom: 12px;
  left: 12px;
  width: 240px;
  height: 102px;
}

.ad.tl {
  top: 108px;
  left: 12px;
  width: 120px;
  height: 182px;
}

.ad.mid {
  top: 46%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 320px;
  height: 136px;
}

@media (max-width: 640px) {
  .ad.tl,
  .ad.bl {
    display: none;
  }
  .ad.mid {
    width: 260px;
    height: 110px;
  }
  .ad.br {
    width: 120px;
    height: 162px;
  }
}

/* ===== 直播角标（滚动层之外，固定窗口右下、购物车条上方） ===== */
.live {
  position: absolute;
  bottom: 68px;
  right: 12px;
  z-index: 95;
  width: 268px;
  border-radius: 12px;
  overflow: hidden;
  background: #fff;
  box-shadow: 0 14px 40px rgba(0, 0, 0, 0.5);
}

@media (max-width: 900px) {
  .live {
    right: 12px;
  }
}

.live .x {
  position: absolute;
  top: 7px;
  right: 7px;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: none;
  background: rgba(0, 0, 0, 0.35);
  color: #fff;
  font-size: 0.75rem;
  line-height: 1;
  cursor: pointer;
  z-index: 3;
}

.live-top {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  background: linear-gradient(135deg, #e8442e, #ff6a00);
  color: #fff;
}

.live-top .dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #fff;
  animation: blink 1.1s infinite;
}

@keyframes blink {
  50% {
    opacity: 0.25;
  }
}

.live-top b {
  font-size: 0.8rem;
}

.live-top .viewers {
  margin-left: auto;
  font-size: 0.6rem;
  opacity: 0.95;
}

.live-body {
  display: flex;
  gap: 10px;
  padding: 12px;
  align-items: center;
}

.live-body .live-cover {
  width: 82px;
  height: 54px;
  border-radius: 8px;
  object-fit: cover;
  border: 1px solid #f0b492;
  flex: none;
}

.live-body .inf {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.live-body .inf .nm {
  font-size: 0.78rem;
  font-weight: bold;
  color: #3a2a1e;
}

.live-body .inf .ds {
  font-size: 0.6rem;
  color: #96755c;
  line-height: 1.4;
}

.live-body .go-live {
  margin-top: 5px;
  align-self: flex-start;
  min-height: 26px;
  border: 1px solid #ff6a00;
  background: #fff;
  color: #e8442e;
  font-weight: bold;
  font-size: 0.64rem;
  border-radius: 999px;
  padding: 0 12px;
  cursor: pointer;
}

/* ===== 客服 · 小镜 ===== */
.kefu-fab {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 4px;
  min-height: 30px;
  padding: 0 14px;
  border: 1px solid #ff8a3d;
  border-radius: 999px;
  background: linear-gradient(135deg, #ff8a3d, #e8442e);
  color: #fff;
  font-weight: bold;
  font-size: 0.76rem;
  cursor: pointer;
  transition: transform 0.15s ease;
}
.kefu-fab:hover {
  transform: translateY(-1px);
}

.kefu-window {
  position: absolute;
  top: 100px;
  right: 12px;
  z-index: 97;
  width: 300px;
  height: 380px;
  display: flex;
  flex-direction: column;
  background: #fffdf8;
  border: 1px solid #f2d8c4;
  border-radius: 14px;
  box-shadow: 0 8px 28px rgba(120, 60, 20, 0.22);
  overflow: hidden;
}

.kefu-head {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  background: linear-gradient(135deg, #ff8a3d, #e8442e);
  color: #fff;
  flex: none;
}
.kefu-avatar {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.25);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.95rem;
}
.kefu-title {
  display: flex;
  flex-direction: column;
  line-height: 1.25;
}
.kefu-title b {
  font-size: 0.82rem;
}
.kefu-status {
  font-size: 0.6rem;
  color: #ffe3c4;
}
.kefu-close {
  margin-left: auto;
  width: 22px;
  height: 22px;
  border: none;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.25);
  color: #fff;
  font-size: 0.72rem;
  cursor: pointer;
}

.kefu-body {
  flex: 1;
  overflow-y: auto;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.kefu-msg {
  display: flex;
}
.kefu-msg.bot {
  justify-content: flex-start;
}
.kefu-msg.user {
  justify-content: flex-end;
}
.kefu-msg .bubble {
  max-width: 82%;
  padding: 7px 10px;
  border-radius: 10px;
  font-size: 0.72rem;
  line-height: 1.5;
}
.kefu-msg.bot .bubble {
  background: #f6ede2;
  color: #5b4632;
  border-bottom-left-radius: 3px;
}
.kefu-msg.user .bubble {
  background: linear-gradient(135deg, #ff8a3d, #e8442e);
  color: #fff;
  border-bottom-right-radius: 3px;
}

.kefu-quick {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding: 8px 12px 2px;
  flex: none;
}
.kefu-quick button {
  border: 1px solid #f0c9a6;
  background: #fff;
  color: #c2551f;
  font-size: 0.66rem;
  border-radius: 999px;
  padding: 3px 10px;
  cursor: pointer;
}
.kefu-quick button:hover {
  background: #fff1e3;
}

.kefu-input {
  display: flex;
  gap: 6px;
  padding: 8px 12px 10px;
  flex: none;
}
.kefu-input input {
  flex: 1;
  min-width: 0;
  height: 30px;
  border: 1px solid #e8d5c2;
  border-radius: 999px;
  padding: 0 12px;
  font-size: 0.72rem;
  background: #fff;
  color: #4a3525;
  outline: none;
}
.kefu-input button {
  min-height: 30px;
  border: none;
  border-radius: 999px;
  background: linear-gradient(135deg, #ff8a3d, #e8442e);
  color: #fff;
  font-size: 0.7rem;
  font-weight: bold;
  padding: 0 14px;
  cursor: pointer;
}

@media (max-width: 480px) {
  .goods-grid {
    grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
  }
}
