
.body-diagram {
  position: relative;
  border: 1px solid var(--c-border);
  border-radius: var(--r-radius);
  background: var(--c-panel);
  padding: 10px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  align-items: center;
  box-shadow: var(--shadow-panel);
}

/* 左侧折叠面板：图层筛选 + 缩放 */
.diagram-tools {
  position: absolute;
  left: 8px;
  top: 8px;
  z-index: 10;
  display: flex;
  flex-direction: column;
  gap: 5px;
  align-items: flex-start;
}

.tool-toggle {
  min-width: 30px;
  min-height: 44px;
  padding: 4px 6px;
  font-size: 0.68rem;
  line-height: 1.25;
  color: var(--c-text-dim);
  background: rgba(13, 18, 27, 0.82);
  border: 1px solid var(--c-border);
  border-radius: 7px;
  cursor: pointer;
  backdrop-filter: blur(3px);
  transition: color 0.15s ease, border-color 0.15s ease;
}

.tool-toggle:hover,
.tool-toggle.open {
  color: var(--c-info);
  border-color: var(--c-info);
}

/* L1/L2/L3 快速切换：竖排小按钮，与折叠按钮同宽 */
.layer-quick {
  display: flex;
  flex-direction: column;
  gap: 3px;
  align-items: stretch;
}

.layer-quick button {
  min-width: 30px;
  min-height: 26px;
  padding: 0 4px;
  font-size: 0.66rem;
  font-family: inherit;
  color: var(--c-text-dim);
  background: rgba(13, 18, 27, 0.82);
  border: 1px solid var(--c-border);
  border-radius: 6px;
  cursor: pointer;
  backdrop-filter: blur(3px);
  transition: color 0.15s ease, border-color 0.15s ease, background 0.15s ease;
}

.layer-quick button:hover {
  color: var(--c-text);
  border-color: var(--c-info);
}

.layer-quick button.active {
  color: var(--c-info);
  border-color: var(--c-info);
  background: rgba(90, 167, 240, 0.18);
}

.tool-panel {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 8px 9px;
  background: rgba(13, 18, 27, 0.9);
  border: 1px solid var(--c-border);
  border-radius: 8px;
  backdrop-filter: blur(4px);
  min-width: 118px;
}

.tp-title {
  font-size: 0.66rem;
  color: var(--c-text-dim);
  letter-spacing: 0.08em;
  margin-top: 2px;
}

.tp-title + .tp-title {
  margin-top: 3px;
}

.tp-item {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 0.72rem;
  color: var(--c-text);
  cursor: pointer;
  user-select: none;
  min-height: 24px;
}

.tp-item input {
  accent-color: var(--c-info);
  width: 13px;
  height: 13px;
}

/* 拖动模式开关：右侧小指示灯 */
.tp-drag {
  position: relative;
}

.tp-drag .drag-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--c-text-dim);
  transition: background 0.2s ease, box-shadow 0.2s ease;
}

.tp-drag .drag-dot.on {
  background: var(--c-info);
  box-shadow: 0 0 6px var(--c-info);
}

/* 拖动模式激活：整个图区域光标变抓取，禁止选中文本 */
.body-svg.dragging {
  cursor: grab;
  user-select: none;
  -webkit-user-select: none;
}

.tp-zoom {
  display: flex;
  align-items: center;
  gap: 4px;
}

.tp-zoom button {
  min-width: 26px;
  min-height: 26px;
  font-size: 0.85rem;
  line-height: 1;
  color: var(--c-text);
  background: rgba(35, 45, 63, 0.9);
  border: 1px solid var(--c-border);
  border-radius: 6px;
  cursor: pointer;
}

.tp-zoom button:hover {
  border-color: var(--c-info);
  color: var(--c-info);
}

.tp-pct {
  flex: 1;
  text-align: center;
  font-size: 0.72rem;
  color: var(--c-info);
  font-variant-numeric: tabular-nums;
}

.tp-reset {
  min-height: 24px;
  font-size: 0.7rem;
  color: var(--c-text);
  background: rgba(35, 45, 63, 0.9);
  border: 1px solid var(--c-border);
  border-radius: 6px;
  cursor: pointer;
}

.tp-reset:hover {
  border-color: var(--c-info);
  color: var(--c-info);
}

.body-svg {
  width: 100%;
  max-width: 340px;
  max-height: 480px;
  display: block;
}

/* 15 段 path：颜色按四档状态注入，不硬编码（任务书第八节） */
.seg {
  fill: var(--seg-fill);
  stroke: var(--seg-stroke);
  stroke-width: 1.5;
  stroke-linejoin: round;
  transition: fill 0.2s ease, stroke 0.2s ease, filter 0.2s ease;
  cursor: pointer;
}

.seg:hover {
  filter: brightness(1.25);
}

.seg.selected {
  stroke: #ffffff;
  stroke-width: 3;
  filter: drop-shadow(0 0 6px var(--seg-stroke)) brightness(1.3);
}

/* L2/L3 模式：躯体主干作为淡色底图（透明度由设置页 segDimOpacity 控制），且不可点击——此时只交互部件层 */
.seg-dim {
  pointer-events: none;
  filter: none !important;
}

.seg-完好 {
  --seg-fill: rgba(65, 216, 163, 0.30);
  --seg-stroke: #41d8a3;
}

.seg-受损 {
  --seg-fill: rgba(232, 182, 76, 0.36);
  --seg-stroke: #e8b64c;
}

.seg-损毁 {
  --seg-fill: rgba(229, 96, 96, 0.42);
  --seg-stroke: #e56060;
}

.seg-拆除 {
  --seg-fill: rgba(92, 102, 117, 0.14);
  --seg-stroke: #5c6675;
}

/* 皮肤外壳层：虚线内层轮廓（仅装饰，不拦截点击） */
.shell-layer .shell-line {
  fill: none;
  stroke: var(--c-border-light);
  stroke-width: 1.2;
  stroke-dasharray: 10 8;
  opacity: 0.35;
  pointer-events: none;
}

/* 机械骨骼 */
.bone-line {
  fill: none;
  stroke: var(--c-info);
  stroke-width: 5;
  opacity: 0.28;
  stroke-linecap: round;
  pointer-events: none;
}

/* 内部功能部件 */
.ipart {
  fill: rgba(90, 167, 240, 0.22);
  stroke: var(--c-info);
  stroke-width: 1.6;
  cursor: pointer;
  transition: fill 0.2s ease, stroke 0.2s ease, filter 0.2s ease;
}

/* 线状部件（骨骼/传感线）：无填充，加粗便于点击 */
.ipart-line {
  fill: none;
  stroke-width: 3.2;
}

.ipart:hover {
  fill: rgba(90, 167, 240, 0.42);
  filter: brightness(1.25);
}

.ipart.selected {
  stroke: #ffffff;
  stroke-width: 2.6;
  fill: rgba(90, 167, 240, 0.5);
  filter: drop-shadow(0 0 6px var(--c-info));
}

/* 子部件级高亮（highlighted 联动：展开子卡=只高亮该卡部件；全收=模块全部子项部件） */
.ipart.hl {
  stroke: #ffffff;
  stroke-width: 2.6;
  fill: rgba(90, 167, 240, 0.5);
  filter: drop-shadow(0 0 6px var(--c-info));
}

.ipart-dots {
  cursor: pointer;
}

.ipart-dots circle {
  fill: rgba(90, 167, 240, 0.5);
  stroke: var(--c-info);
  stroke-width: 1.2;
  transition: fill 0.2s ease;
}

.ipart-dots:hover circle {
  fill: rgba(90, 167, 240, 0.8);
}

.ipart-dots.selected circle,
.ipart-dots.hl circle {
  fill: rgba(255, 255, 255, 0.75);
  stroke: #ffffff;
}

.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: center;
}

.legend-item {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 0.72rem;
  color: var(--c-text-dim);
}

.dot {
  width: 10px;
  height: 10px;
  border-radius: 2px;
  display: inline-block;
}

.dot-完好 { background: #41d8a3; }
.dot-受损 { background: #e8b64c; }
.dot-损毁 { background: #e56060; }
.dot-拆除 { background: #5c6675; }
.dot-module { background: rgba(90, 167, 240, 0.6); border: 1px solid var(--c-info); }

.hint-line {
  font-size: 0.7rem;
  color: var(--c-text-dim);
  text-align: center;
}
