
.settle-panel {
  border: 1px solid var(--c-border);
  border-radius: var(--r-radius);
  background: var(--c-panel);
  padding: 10px;
}

.head {
  font-size: 0.86rem;
  font-weight: bold;
  color: var(--c-accent);
  border-bottom: 1px solid var(--c-border);
  padding-bottom: 5px;
  margin-bottom: 8px;
}

.empty {
  color: var(--c-text-dim);
  padding: 10px 0;
  font-size: 0.8rem;
}

.settle-row {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  border: 1px solid var(--c-border);
  padding: 8px;
  margin-bottom: 6px;
  background: var(--c-panel-2);
  border-left: 3px solid var(--c-accent);
}

.s-name {
  font-weight: bold;
  flex: 1;
  min-width: 100px;
  font-size: 0.82rem;
}

.s-days,
.s-money,
.s-fans,
.s-fame {
  font-size: 0.76rem;
  color: var(--c-text-dim);
}

.s-money {
  color: var(--c-accent);
  font-weight: bold;
}

.note {
  margin-top: 6px;
  color: var(--c-text-dim);
  font-size: 0.7rem;
  line-height: 1.5;
}
