
.map-panel {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

/* ===== 地图横幅 + 定位针（方案 C） ===== */
.map-sec {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.mapbanner {
  position: relative;
  border: 1px solid var(--c-border-light);
  border-radius: var(--r-radius);
  overflow: hidden;
  background: #0b0e14;
  box-shadow: 0 10px 40px -18px rgba(0, 0, 0, 0.8);
}

.mapbanner img {
  width: 100%;
  display: block;
  aspect-ratio: 21 / 9;
  object-fit: cover;
  object-position: center 40%;
  user-select: none;
}

.map-veil {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(180deg, rgba(11, 14, 20, 0.3) 0%, rgba(11, 14, 20, 0.05) 30%, rgba(11, 14, 20, 0.05) 60%, rgba(11, 14, 20, 0.42) 100%);
}

.pin {
  position: absolute;
  width: 22px;
  height: 26px;
  cursor: pointer;
  transform: translate(-50%, -100%);
  filter: drop-shadow(0 2px 3px rgba(0, 0, 0, 0.6));
  z-index: 3;
  background: none;
  border: 0;
  padding: 0;
}

/* 清除 global.css 标题装饰体系对 .head 注入的 ::before 圆点 / ::after 细线 */
.pin .head::before,
.pin .head::after {
  content: none;
}

.pin .head {
  position: absolute;
  left: 50%;
  top: 0;
  width: 18px;
  height: 18px;
  border-radius: 50% 50% 50% 0;
  background: var(--zac, #e8a34c);
  border: 2px solid #0b0e14;
  transform: translateX(-50%) rotate(-45deg);
  box-shadow: 0 0 12px -3px var(--zac, #e8a34c);
  transition: box-shadow 0.15s;
}

.pin .core {
  position: absolute;
  left: 50%;
  top: 6px;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #0b0e14;
  transform: translateX(-50%);
}

.pin:hover .head {
  box-shadow: 0 0 16px -2px var(--zac, #e8a34c);
}

.pin.sel .head {
  outline: 3px solid rgba(255, 255, 255, 0.75);
  outline-offset: 2px;
}

.pin .tip {
  position: absolute;
  left: 50%;
  bottom: calc(100% + 6px);
  transform: translateX(-50%);
  white-space: nowrap;
  font-size: 0.62rem;
  font-weight: 700;
  color: var(--c-text);
  background: rgba(12, 15, 22, 0.94);
  border: 1px solid var(--c-border-light);
  padding: 3px 8px;
  border-radius: 7px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.15s;
  letter-spacing: 0.02em;
}

.pin:hover .tip,
.pin.sel .tip {
  opacity: 1;
}

/* 当前活动地点：名称常显（金色，与样板一致） */
.pin.current .tip {
  opacity: 1;
  color: #ffd58a;
  border-color: rgba(255, 213, 138, 0.4);
}

/* ===== 当前活动地点：金色脉冲波纹（双圈扩散） ===== */
.pin.current::before,
.pin.current::after {
  content: '';
  position: absolute;
  left: 50%;
  top: 9px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  border: 2px solid #ffd58a;
  transform: translate(-50%, -50%);
  z-index: -1;
}

.pin.current::before {
  animation: mapPulse 1.7s ease-out infinite;
}

.pin.current::after {
  animation: mapPulse 1.7s ease-out 0.85s infinite;
}

@keyframes mapPulse {
  0% {
    opacity: 0.9;
    transform: translate(-50%, -50%) scale(0.5);
  }
  100% {
    opacity: 0;
    transform: translate(-50%, -50%) scale(3.2);
  }
}

/* ===== 前往栏 ===== */
.go-bar {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  border: 1px solid var(--c-border-light);
  border-radius: var(--r-radius);
  background: rgba(18, 23, 34, 0.92);
  backdrop-filter: blur(6px);
}

.go-bar .st {
  font-size: 0.68rem;
  color: var(--c-text-dim);
  flex: none;
}

.go-bar .sel-name {
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--c-accent);
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.go-bar .cost {
  font-size: 0.64rem;
  color: var(--c-text-dim);
  flex: none;
}

.go-btn,
.home-btn {
  flex: none;
  font-size: 0.74rem;
  font-weight: 700;
  color: #0b0e14;
  background: var(--c-accent);
  border: 0;
  border-radius: 8px;
  padding: 6px 14px;
  cursor: pointer;
  font-family: inherit;
  letter-spacing: 0.06em;
  transition: filter 0.12s, transform 0.12s;
}

.go-btn:disabled {
  background: #2a3140;
  color: #5a6a7c;
  cursor: not-allowed;
}

.go-btn:not(:disabled):hover,
.home-btn:hover {
  filter: brightness(1.12);
}

.home-btn {
  background: #2a3344;
  color: var(--c-text);
  border: 1px solid var(--c-border-light);
}

/* ===== 当前活动地点横幅（仅 section 元素，避免污染带 current 类的定位针） ===== */
section.current {
  border: 1px solid var(--c-border-light);
  border-left: 4px solid var(--c-accent);
  border-radius: var(--r-radius);
  background: var(--c-panel-2);
  box-shadow: var(--shadow-panel);
}

.cur-inner {
  padding: 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.cur-label {
  color: var(--c-text-dim);
  font-size: 0.7rem;
  letter-spacing: 0.08em;
}

.cur-name {
  color: var(--c-accent);
  font-weight: bold;
  font-size: 1.02rem;
}

.cur-desc {
  color: var(--c-text);
  font-size: 0.76rem;
}

.cur-hint {
  color: var(--c-text-dim);
  font-size: 0.7rem;
  line-height: 1.5;
}

/* ===== 充电站：充电档选择 ===== */
section.charge {
  border: 1px solid #6fae7c;
  border-left: 4px solid #6fae7c;
  border-radius: var(--r-radius);
  background: var(--c-panel-2);
  box-shadow: var(--shadow-panel);
}

.charge-inner {
  padding: 10px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.charge-title {
  color: #9fcfae;
  font-weight: bold;
  font-size: 0.88rem;
}

.charge-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.charge-btn {
  font-size: 0.76rem;
  font-weight: 700;
  color: #0b0e14;
  background: #6fae7c;
  border: 0;
  border-radius: 8px;
  padding: 7px 14px;
  cursor: pointer;
  font-family: inherit;
  letter-spacing: 0.04em;
  transition: filter 0.12s;
}

.charge-btn.slow {
  background: #4d7a5c;
  color: #eaf5ee;
}

.charge-btn:hover {
  filter: brightness(1.12);
}

.charge-note {
  color: var(--c-text-dim);
  font-size: 0.68rem;
}

/* 分区 */
.zone {
  border: 1px solid var(--c-border);
  border-left: 3px solid var(--zone-accent);
  border-radius: var(--r-radius);
  background: var(--c-panel);
  padding: 10px;
  box-shadow: var(--shadow-panel);
}

.zone-head {
  display: flex;
  align-items: center;
  gap: 7px;
  border-bottom: 1px solid var(--c-border);
  padding-bottom: 6px;
  margin-bottom: 8px;
}

.zone-fold {
  margin-left: auto;
  flex: none;
  font-size: 0.64rem;
  font-weight: 700;
  color: var(--c-text-dim);
  background: var(--c-panel-2);
  border: 1px solid var(--c-border);
  border-radius: 6px;
  padding: 2px 9px;
  cursor: pointer;
  font-family: inherit;
  transition: color 0.12s, border-color 0.12s;
}

.zone-fold:hover {
  color: var(--c-text);
  border-color: var(--c-border-light);
}

.zone-dot {
  width: 9px;
  height: 9px;
  border-radius: 2px;
  background: var(--zone-accent);
  display: inline-block;
}

.zone-title {
  font-size: 0.86rem;
  font-weight: bold;
  color: var(--zone-accent);
}

.zone-sub {
  font-size: 0.68rem;
  color: var(--c-text-dim);
}

.place-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 8px;
}

.place-grid.hidden {
  display: none;
}

.place {
  min-height: 92px;
  padding: 8px;
  border: 1px solid var(--c-border);
  border-radius: var(--r-radius);
  background: var(--c-panel-2);
  color: var(--c-text);
  cursor: pointer;
  display: flex;
  flex-direction: column;
  gap: 3px;
  align-items: flex-start;
  text-align: left;
  transition: border-color 0.15s, background 0.15s;
}

.place:hover {
  border-color: var(--zone-accent);
}

.place.selected {
  border-color: var(--zone-accent);
  background: color-mix(in srgb, var(--zone-accent) 16%, var(--c-panel));
  box-shadow: 0 0 0 1px var(--zone-accent);
}

.place:active {
  transform: translateY(1px);
}

/* 维修店入口卡 */
.place.shop {
  border-color: #e8a34c;
  background: linear-gradient(160deg, rgba(232, 163, 76, 0.16), rgba(232, 163, 76, 0.05) 60%, transparent);
}

.place.shop:hover {
  box-shadow: 0 0 0 1px #e8a34c;
}

.p-badge {
  font-size: 0.62rem;
  color: #ffb36b;
  border: 1px solid #5a4630;
  background: rgba(232, 163, 76, 0.1);
  border-radius: 6px;
  padding: 0 6px;
  margin-top: 2px;
}

.p-badge.danger {
  color: #ff8a7a;
  border-color: #7a3a2a;
  background: rgba(180, 60, 40, 0.14);
}

.p-cost {
  font-size: 0.64rem;
  color: var(--c-text-dim);
  margin-top: 2px;
}

.map-tip {
  border: 1px solid var(--c-border);
  border-left: 3px solid var(--c-accent);
  border-radius: var(--r-radius);
  background: var(--c-panel);
  padding: 8px 10px;
  font-size: 0.74rem;
  color: var(--c-text);
}

.p-icon {
  font-size: 1.1rem;
  color: var(--zone-accent);
  line-height: 1;
}

.p-name {
  font-weight: bold;
  font-size: 0.82rem;
}

.p-desc {
  color: var(--c-text-dim);
  font-size: 0.7rem;
  line-height: 1.4;
  flex: 1;
}

.foot-note {
  color: var(--c-text-dim);
  font-size: 0.72rem;
  line-height: 1.5;
  padding: 0 2px;
}
