
.console {
  width: 100%;
  max-width: 720px;
  margin: 0 auto;
  background: var(--c-bg);
  border: 2px solid var(--c-border);
  display: flex;
  flex-direction: column;
  /* 高度由内容决定：内容区固定高度后不再撑满视口，避免底部空出大黑边 */
}

.content {
  padding: 12px;
  /* 内容区为纵向 flex：面板（如物品页）可撑满到底部铺平界面 */
  display: flex;
  flex-direction: column;
  /* 电脑端：各标签页统一固定高度（=机体页完整显示人体图的高度 + 余量），超出区内滚动；高度可在设置页调整 */
  height: var(--content-h, 720px);
  overflow-y: auto;
}

/* 手机端：内容区固定统一高度（恰好完整显示人体图），超出部分区内滚动 */
@media (max-width: 480px) {
  .console {
    min-height: 0;
  }

  .content {
    flex: none;
    height: 612px;
    overflow-y: auto;
    scrollbar-width: none;
    padding: 8px;
  }

  .content::-webkit-scrollbar {
    display: none;
  }
}
